// Beginner course ("はじめてのチェス") strings for 10 languages. Loaded after i18n.js and merged into window.I18N.
(function () {
const B = {"ja":{"ls.desc":"ルールを知らなくても大丈夫。「はじめてのチェス」で駒の動きから対局のしかたまで、盤の上で駒を動かしながら覚えられます。そのあとは「戦術」で勝ち方の型を学びましょう（各問20点、75点以上で合格）。","course.basics":"はじめてのチェス","course.basics.sub":"ルールをまったく知らない人向け。駒の動き → 取る → チェック → チェックメイト → 特別なルール → 引き分け、の順に、盤で駒を動かして覚えます。","course.tactics":"戦術","course.tactics.sub":"ルールを覚えたら次はこちら。駒得やフォーク、詰みの形など、勝つための考え方を学びます。","course.graduate":"🎉「はじめてのチェス」修了です！これでチェスのルールはすべて覚えました。いちばんやさしいAI（Lv.1）と実際に対局してみましょう。対局中は駒をタップすると、動けるマスが表示されます。","course.play":"AI（Lv.1）と対局する","dr.start":"駒をタップ（またはドラッグ）して動かし、★をすべて集めましょう。目標は{p}手です。","dr.par":"（目標{p}手）","dr.reset":"やり直す","dr.progress":"{n}手目。★はあと{left}個です。","dr.clear":"クリア！","dr.used":"{n}手で集めました（目標{p}手）。","dr.tryPar":"「やり直す」で目標手数にも挑戦できます。","dr.danger":"そのマスは相手の駒に取られてしまいます。赤いしま模様のマスには止まれません。","dr.more":"★3つは目標手数どおりにクリアした印です。","ill.self":"その手は指せません。動かすと自分のキングが取られる形になります。","ill.inCheck":"王手（チェック）されています。まずキングを守る手を指しましょう。","ls.b_rook.title":"ルーク","ls.b_rook.sub":"タテ・ヨコにどこまでも進む","ls.b_rook.intro":"<p>チェスは<b>8×8マス</b>の盤で、白と黒が交互に1手ずつ駒を動かすゲームです。白が先に指します。相手の<b>キングを追い詰めたら勝ち</b>（チェックメイト）。まずは駒の動きを1つずつ覚えましょう。</p><p><b>ルーク</b>（城の形の駒）は<b>タテとヨコ</b>に、何マスでも進めます。ただし、ほかの駒を飛び越えることはできません。</p><p class=\"note\">盤の上の★を、ルークを動かしてすべて集めてください。点の付いたマスが動けるマスです。</p>","ls.b_rook.goal":"ルークで★をすべて集めよう。","ls.b_bishop.title":"ビショップ","ls.b_bishop.sub":"ナナメにどこまでも進む","ls.b_bishop.intro":"<p><b>ビショップ</b>（とんがり帽子の駒）は<b>ナナメ</b>に、何マスでも進めます。</p><p>ナナメにしか動かないので、ビショップは<b>ずっと同じ色のマス</b>にいます。白マスのビショップと黒マスのビショップ、それぞれ1つずつ持っています。</p>","ls.b_bishop.goal":"ビショップで★をすべて集めよう。","ls.b_queen.title":"クイーン","ls.b_queen.sub":"いちばん強い駒","ls.b_queen.intro":"<p><b>クイーン</b>（王冠の駒）は、ルークとビショップを合わせた動きをします。<b>タテ・ヨコ・ナナメ</b>のどの方向にも、何マスでも進めます。</p><p>いちばん強い駒なので、うっかり取られないように大切に使いましょう。</p>","ls.b_queen.goal":"クイーンで★をすべて集めよう。","ls.b_king.title":"キング","ls.b_king.sub":"いちばん大切な駒","ls.b_king.intro":"<p><b>キング</b>（十字の付いた駒）は、まわりの<b>8方向に1マスだけ</b>動けます。</p><p>キングは取られてはいけない、いちばん大切な駒です。キングが逃げられなくなると負けになります。</p>","ls.b_king.goal":"キングで★をすべて集めよう。","ls.b_knight.title":"ナイト","ls.b_knight.sub":"L字に跳ぶ","ls.b_knight.intro":"<p><b>ナイト</b>（馬の駒）は<b>「タテに2マス・ヨコに1マス」または「ヨコに2マス・タテに1マス」</b>の、L字の形に動きます。</p><p>ナイトだけは、ほかの駒を<b>飛び越えられます</b>。また、ナイトが跳ぶたびにマスの色（白・黒）が変わります。</p>","ls.b_knight.goal":"ナイトで★をすべて集めよう。","ls.b_pawn.title":"ポーン","ls.b_pawn.sub":"前に進み、ナナメに取る","ls.b_pawn.intro":"<p><b>ポーン</b>（いちばん小さい駒）は<b>前に1マス</b>だけ進みます。後ろには戻れません。ただし<b>最初の1回だけは2マス</b>進めます。</p><p>相手の駒を取るときだけは<b>ナナメ前に1マス</b>動きます。まっすぐ前に駒があると、ポーンは進めません。</p><p>ポーンが<b>いちばん奥の段</b>に着くと、クイーンなどの好きな駒に<b>成る（昇格する）</b>ことができます。ふつうはクイーンを選びます。</p>","ls.b_pawn.goal":"ポーンで★をすべて集めよう。","ls.b_capture.title":"駒を取る","ls.b_capture.sub":"相手の駒のマスに入る","ls.b_capture.intro":"<p>自分の駒が動けるマスに相手の駒があれば、そこへ動いて<b>取る</b>ことができます。取られた駒は盤から消えます。</p><p>駒にはおおよその価値があります：<b>ポーン1・ナイト3・ビショップ3・ルーク5・クイーン9</b>。価値の高い駒をたくさん残したほうが有利です。</p><p class=\"note\">★の上にいる黒い駒を、すべて取ってください（黒い駒は動きません）。</p>","ls.b_capture.goal":"★の上の黒い駒をすべて取ろう。","ls.b_safety.title":"取られないマス","ls.b_safety.sub":"相手の駒がねらうマスに注意","ls.b_safety.intro":"<p>相手の駒が動けるマスに自分の駒を置くと、次の手で<b>取られてしまいます</b>。</p><p>この練習では、黒い駒がねらっているマスが<b>赤いしま模様</b>で表示されます。そこには止まれないので、遠回りして★を集めましょう。</p><p class=\"note\">実際の対局でも、駒を動かす前に「そのマスは相手にねらわれていないか？」を確かめる習慣をつけましょう。</p>","ls.b_safety.goal":"取られないマスだけを通って★を集めよう。","ls.b_check.title":"チェック（王手）","ls.b_check.sub":"キングをねらう","ls.b_check.intro":"<p>相手の<b>キングを取れる状態にする手</b>を<b>チェック</b>（王手）といいます。</p><p>チェックされた側は、次の手で必ずキングを守らなければなりません。ここからは本物の対局と同じルールで、白番の手を1つ選びます。</p>","ls.b_check.goal":"黒のキングにチェックをかけよう。","ls.b_check.hint":"赤い枠が黒のキング。そこへ届く線や跳び方を探そう。","ls.b_check.why":"正解！ {m} でチェック（王手）です。","ls.b_check.ng":"その手はチェックになっていません。正解の一例：{m}","ls.b_escape.title":"チェックから逃げる","ls.b_escape.sub":"3つの守り方","ls.b_escape.intro":"<p>チェックされたら、次の3つのどれかで守ります。</p><p>①<b>キングを逃がす</b>（ねらわれていないマスへ）<br>②<b>あいだに駒を置く</b>（ナイトのチェックには使えません）<br>③<b>チェックしている駒を取る</b></p><p>チェックを放っておく手は、ルール上指せません。どの手がいちばん良いかを考えましょう。</p>","ls.b_escape.goal":"チェックから守る、いちばん良い手を。","ls.b_escape.hint":"赤い枠が自分のキング、ピンクの枠がチェックしている駒です。取れるなら取るのがいちばん。","ls.b_escape.why":"{m} が最善です。キングを守りつつ、駒を損しない手です。","ls.b_mate.title":"チェックメイト","ls.b_mate.sub":"これで勝ち！","ls.b_mate.intro":"<p>チェックされたキングが、<b>逃げることも、あいだに駒を置くことも、チェックしている駒を取ることもできない</b>状態を<b>チェックメイト</b>といいます。チェックメイトにしたほうの<b>勝ち</b>です。</p><p>図は「バックランクメイト」。自分のポーンが壁になってキングが逃げられません。</p>","ls.b_mate.goal":"1手でチェックメイトにしよう。","ls.b_mate.hint":"赤い枠が黒のキング。チェックをかけたあと、キングが逃げられるマスが残らない手を探そう。","ls.b_mate.why":"チェックメイト！ {m} で黒のキングはどこにも逃げられません。","ls.b_mate.ng":"その手ではチェックメイトになりません。正解：{m}","ls.b_special.title":"特別なルール","ls.b_special.sub":"キャスリング・アンパッサン・昇格","ls.b_special.intro":"<p><b>キャスリング</b>：キングとルークが一度も動いておらず、間に駒がないとき、<b>キングを横に2マス</b>動かし、ルークをキングの反対側へ移します（1手で2つ動かせる特別な手）。キングがチェックされているとき・通り道がねらわれているときはできません。キングを安全な隅に移せます。</p><p><b>アンパッサン</b>：相手のポーンが最初の2マス進みで自分のポーンの<b>真横に来た直後</b>だけ、そのポーンを<b>ナナメ前に進んで取れます</b>。</p><p><b>昇格（プロモーション）</b>：ポーンが奥の段に着いたら、クイーンなどに成ります。</p><p class=\"note\">キャスリングは、キングを横に2マス動かすと行えます。</p>","ls.b_special.goal":"特別なルールを使ってみよう（キャスリング・アンパッサン・昇格）。","ls.b_special.hint":"金の枠の駒を動かします。","ls.b_special.why":"正解！ {m} です。","ls.b_special.ng":"今回の正解は {m} でした。キャスリングはキングを横に2マス、アンパッサンはナナメに取る、昇格はクイーンを選びます。","ls.b_draw.title":"引き分け","ls.b_draw.sub":"ステイルメイトに注意","ls.b_draw.intro":"<p>手番の側が<b>チェックされていないのに、指せる手が1つもない</b>状態を<b>ステイルメイト</b>といい、<b>引き分け</b>になります。図では黒のキングはチェックされていませんが、どこに動いても取られてしまうので指せません。</p><p>勝っているときにステイルメイトにしてしまうのは、よくある失敗です。相手のキングに逃げ場を1つ残すか、チェックメイトにしましょう。</p><p class=\"note\">ほかにも、同じ局面が3回くり返す・50手のあいだ駒取りもポーンの動きもない・どちらもチェックメイトできる駒が残っていない、などで引き分けになります。</p>","ls.b_draw.goal":"ステイルメイトにせず、勝ちにつながる手を。","ls.b_draw.hint":"赤い枠が黒のキング。その手のあと、黒に指せる手が残るか（またはチェックメイトか）を確かめよう。","ls.b_draw.why":"{m} が最善です。ステイルメイトにせず、勝ちに近づきます。"},
"en":{"ls.desc":"No need to know the rules. \"Chess from zero\" teaches you everything from how the pieces move to playing a game, by moving pieces on the board. Then learn winning patterns in \"Tactics\" (20 points per problem, 75 to pass).","course.basics":"Chess from zero","course.basics.sub":"For complete beginners. Piece moves → captures → check → checkmate → special rules → draws, learned by moving pieces on the board.","course.tactics":"Tactics","course.tactics.sub":"Once you know the rules: winning material, forks, mating patterns and other ways to win.","course.graduate":"🎉 You finished \"Chess from zero\" — you now know all the rules of chess! Try a real game against the gentlest AI (Lv.1). During a game, tap a piece to see where it can move.","course.play":"Play the AI (Lv.1)","dr.start":"Tap (or drag) the piece to move it and collect every ★. Target: {p} moves.","dr.par":"(target: {p} moves)","dr.reset":"Restart","dr.progress":"Move {n}. {left} ★ left.","dr.clear":"Cleared!","dr.used":"You used {n} moves (target {p}).","dr.tryPar":"Press \"Restart\" to try for the target.","dr.danger":"That square is attacked — your piece would be captured. You can't stop on the red striped squares.","dr.more":"Three stars means you cleared the stage in the target number of moves.","ill.self":"You can't play that: it would leave your own king open to capture.","ill.inCheck":"Your king is in check. You must protect it first.","ls.b_rook.title":"The rook","ls.b_rook.sub":"Any distance straight up, down or sideways","ls.b_rook.intro":"<p>Chess is played on an <b>8×8 board</b>. White and Black take turns moving one piece; White moves first. You <b>win by trapping the enemy king</b> (checkmate). First, let's learn how each piece moves.</p><p>The <b>rook</b> (the castle) moves <b>straight along ranks and files</b>, any number of squares. It cannot jump over other pieces.</p><p class=\"note\">Move the rook to collect all the ★ on the board. Dots show the squares it can reach.</p>","ls.b_rook.goal":"Collect every ★ with the rook.","ls.b_bishop.title":"The bishop","ls.b_bishop.sub":"Any distance diagonally","ls.b_bishop.intro":"<p>The <b>bishop</b> (the pointed hat) moves <b>diagonally</b>, any number of squares.</p><p>Because it only moves diagonally, a bishop <b>always stays on the same colour</b>. Each side has one light-squared and one dark-squared bishop.</p>","ls.b_bishop.goal":"Collect every ★ with the bishop.","ls.b_queen.title":"The queen","ls.b_queen.sub":"The strongest piece","ls.b_queen.intro":"<p>The <b>queen</b> (the crown) combines the rook and the bishop: it moves <b>straight or diagonally</b>, any number of squares.</p><p>It is the most powerful piece, so take care not to lose it.</p>","ls.b_queen.goal":"Collect every ★ with the queen.","ls.b_king.title":"The king","ls.b_king.sub":"The most important piece","ls.b_king.intro":"<p>The <b>king</b> (with the cross) moves <b>one square in any direction</b>.</p><p>The king must never be captured. If your king cannot escape, you lose.</p>","ls.b_king.goal":"Collect every ★ with the king.","ls.b_knight.title":"The knight","ls.b_knight.sub":"Jumps in an L shape","ls.b_knight.intro":"<p>The <b>knight</b> (the horse) moves in an <b>L shape: two squares one way and one square to the side</b>.</p><p>It is the only piece that can <b>jump over</b> other pieces. Every jump also changes the colour of its square.</p>","ls.b_knight.goal":"Collect every ★ with the knight.","ls.b_pawn.title":"The pawn","ls.b_pawn.sub":"Moves forward, captures diagonally","ls.b_pawn.intro":"<p>The <b>pawn</b> moves <b>one square forward</b> and never backwards — except that on its <b>first move it may go two squares</b>.</p><p>It <b>captures one square diagonally forward</b>. A pawn blocked by a piece straight ahead cannot move.</p><p>When a pawn reaches the <b>far end</b> of the board it <b>promotes</b> to a queen, rook, bishop or knight — almost always a queen.</p>","ls.b_pawn.goal":"Collect every ★ with the pawn.","ls.b_capture.title":"Capturing","ls.b_capture.sub":"Move onto an enemy piece","ls.b_capture.intro":"<p>If an enemy piece stands on a square your piece can move to, you can move there and <b>capture</b> it. Captured pieces leave the board.</p><p>Pieces have rough values: <b>pawn 1, knight 3, bishop 3, rook 5, queen 9</b>. Keeping more valuable pieces gives you the advantage.</p><p class=\"note\">Capture every black piece standing on a ★ (the black pieces don't move).</p>","ls.b_capture.goal":"Capture every black piece on a ★.","ls.b_safety.title":"Safe squares","ls.b_safety.sub":"Watch what the enemy attacks","ls.b_safety.intro":"<p>If you put a piece where an enemy piece can move, it will be <b>captured</b> on the next move.</p><p>In this drill the squares the black pieces attack are shown with <b>red stripes</b>. You can't stop there, so find a way around to collect the ★.</p><p class=\"note\">In real games, make it a habit to ask \"is that square attacked?\" before every move.</p>","ls.b_safety.goal":"Collect the ★ using only safe squares.","ls.b_check.title":"Check","ls.b_check.sub":"Attack the king","ls.b_check.intro":"<p>A move that <b>attacks the enemy king</b> is called <b>check</b>.</p><p>The side in check must protect its king on the very next move. From here on, the full rules apply: choose one move for White.</p>","ls.b_check.goal":"Give check to the black king.","ls.b_check.hint":"The red frame is the black king. Look for a line or jump that reaches it.","ls.b_check.why":"Correct! {m} gives check.","ls.b_check.ng":"That move doesn't give check. One answer: {m}","ls.b_escape.title":"Getting out of check","ls.b_escape.sub":"Three ways to defend","ls.b_escape.intro":"<p>When you are in check, you must do one of three things:</p><p>① <b>Move the king</b> to a safe square<br>② <b>Block</b> by putting a piece in between (impossible against a knight)<br>③ <b>Capture</b> the checking piece</p><p>Moves that ignore the check are not allowed. Think about which defence is best.</p>","ls.b_escape.goal":"Find the best way out of check.","ls.b_escape.hint":"The red frame is your king, the pink frame the checking piece. Capturing it is best when you can.","ls.b_escape.why":"{m} is best: it saves the king without losing material.","ls.b_mate.title":"Checkmate","ls.b_mate.sub":"This wins the game!","ls.b_mate.intro":"<p>When a king in check <b>cannot move away, cannot be shielded, and the checking piece cannot be captured</b>, it is <b>checkmate</b> — and the side that delivered it <b>wins</b>.</p><p>The diagram shows a \"back-rank mate\": the king's own pawns block its escape.</p>","ls.b_mate.goal":"Checkmate in one move.","ls.b_mate.hint":"The red frame is the black king. Find a check that leaves it no escape square.","ls.b_mate.why":"Checkmate! After {m} the black king has nowhere to go.","ls.b_mate.ng":"That isn't checkmate. The answer: {m}","ls.b_special.title":"Special rules","ls.b_special.sub":"Castling, en passant, promotion","ls.b_special.intro":"<p><b>Castling</b>: if the king and a rook have never moved and nothing stands between them, move the <b>king two squares sideways</b>; the rook jumps to the king's other side — two pieces in one move. Not allowed while in check or through an attacked square. It tucks your king into safety.</p><p><b>En passant</b>: right after an enemy pawn moves two squares and lands <b>beside</b> your pawn, you may capture it <b>diagonally</b> as if it had moved one square.</p><p><b>Promotion</b>: a pawn reaching the last rank becomes a queen (or another piece).</p><p class=\"note\">To castle, move the king two squares sideways.</p>","ls.b_special.goal":"Use a special rule (castling, en passant, promotion).","ls.b_special.hint":"Move the piece in the gold frame.","ls.b_special.why":"Correct! {m}.","ls.b_special.ng":"The answer was {m}. Castle by moving the king two squares sideways; en passant captures diagonally; promote to a queen.","ls.b_draw.title":"Draws","ls.b_draw.sub":"Beware of stalemate","ls.b_draw.intro":"<p>If the side to move is <b>not in check but has no legal move</b>, it is <b>stalemate</b> — a <b>draw</b>. In the diagram the black king is not in check, yet every square it could go to is attacked.</p><p>Stalemating an opponent when you are winning is a classic mistake: leave the king a square, or give checkmate.</p><p class=\"note\">Games are also drawn by threefold repetition, by 50 moves without a capture or pawn move, or when neither side has enough material to mate.</p>","ls.b_draw.goal":"Play a winning move — without stalemating.","ls.b_draw.hint":"The red frame is the black king. After your move, does Black still have a move (or is it mate)?","ls.b_draw.why":"{m} is best: no stalemate, and it brings you closer to the win."},
"zh":{"ls.desc":"不懂规则也没关系。在“国际象棋入门”中，你可以在棋盘上动手走棋，从棋子的走法一直学到如何下完一盘棋。之后再到“战术”里学习取胜的套路（每题20分，75分及格）。","course.basics":"国际象棋入门","course.basics.sub":"适合完全不懂规则的人。按照 棋子走法 → 吃子 → 将军 → 将杀 → 特殊规则 → 和棋 的顺序，在棋盘上动手学习。","course.tactics":"战术","course.tactics.sub":"学会规则后就来这里。学习得子、捉双、将杀的基本形等取胜的思路。","course.graduate":"🎉 你已完成“国际象棋入门”，国际象棋的规则全部学会了！试着和最温和的AI（Lv.1）真正下一盘吧。对局中点击棋子，就会显示它能走到的格子。","course.play":"与AI（Lv.1）对局","dr.start":"点击（或拖动）棋子来走棋，收集所有的★。目标：{p}步。","dr.par":"（目标{p}步）","dr.reset":"重来","dr.progress":"第{n}步。还剩{left}个★。","dr.clear":"过关！","dr.used":"你用了{n}步（目标{p}步）。","dr.tryPar":"点击“重来”，挑战目标步数吧。","dr.danger":"那个格子受到攻击，走过去会被吃掉。红色斜纹的格子不能停留。","dr.more":"三颗★表示你在目标步数内过关。","ill.self":"不能这样走：这会让你自己的王被吃掉。","ill.inCheck":"你的王正被将军。必须先保护王。","ls.b_rook.title":"车","ls.b_rook.sub":"横竖直走，格数不限","ls.b_rook.intro":"<p>国际象棋在<b>8×8的棋盘</b>上进行。白方和黑方轮流各走一个棋子，白方先走。<b>困住对方的王就能获胜</b>（将杀）。首先，来学习每种棋子的走法。</p><p><b>车</b>（城堡形状的棋子）可以<b>沿横线或竖线直走</b>，格数不限，但不能跳过其他棋子。</p><p class=\"note\">走动车，收集棋盘上所有的★。圆点表示它能走到的格子。</p>","ls.b_rook.goal":"用车收集所有的★。","ls.b_bishop.title":"象","ls.b_bishop.sub":"斜着走，格数不限","ls.b_bishop.intro":"<p><b>象</b>（尖帽子形状的棋子）可以<b>斜着走</b>，格数不限。</p><p>因为只能斜走，象<b>永远停在同一种颜色的格子上</b>。双方各有一个走浅色格的象和一个走深色格的象。</p>","ls.b_bishop.goal":"用象收集所有的★。","ls.b_queen.title":"后","ls.b_queen.sub":"最强的棋子","ls.b_queen.intro":"<p><b>后</b>（王冠形状的棋子）兼有车和象的走法：可以<b>直走或斜走</b>，格数不限。</p><p>它是威力最大的棋子，小心别丢掉它。</p>","ls.b_queen.goal":"用后收集所有的★。","ls.b_king.title":"王","ls.b_king.sub":"最重要的棋子","ls.b_king.intro":"<p><b>王</b>（顶上有十字的棋子）可以<b>向任意方向走一格</b>。</p><p>王绝对不能被吃掉。如果你的王无路可逃，你就输了。</p>","ls.b_king.goal":"用王收集所有的★。","ls.b_knight.title":"马","ls.b_knight.sub":"走L形跳跃","ls.b_knight.intro":"<p><b>马</b>（马头形状的棋子）走<b>L形：先朝一个方向走两格，再横向走一格</b>。</p><p>它是唯一可以<b>跳过</b>其他棋子的棋子。每跳一次，所在格子的颜色都会改变。</p>","ls.b_knight.goal":"用马收集所有的★。","ls.b_pawn.title":"兵","ls.b_pawn.sub":"向前走，斜着吃","ls.b_pawn.intro":"<p><b>兵</b>每次<b>向前走一格</b>，不能后退——不过<b>第一步可以走两格</b>。</p><p>它<b>斜向前一格吃子</b>。正前方被棋子挡住时，兵就不能走。</p><p>兵走到棋盘的<b>另一端</b>时会<b>升变</b>为后、车、象或马——几乎总是选后。</p>","ls.b_pawn.goal":"用兵收集所有的★。","ls.b_capture.title":"吃子","ls.b_capture.sub":"走到对方棋子所在的格子","ls.b_capture.intro":"<p>如果对方棋子站在你的棋子能走到的格子上，你就可以走过去把它<b>吃掉</b>。被吃的棋子离开棋盘。</p><p>棋子有大致的价值：<b>兵1、马3、象3、车5、后9</b>。保留更多高价值的棋子，就能占优势。</p><p class=\"note\">吃掉所有站在★上的黑棋（黑棋不会动）。</p>","ls.b_capture.goal":"吃掉★上所有的黑棋。","ls.b_safety.title":"安全的格子","ls.b_safety.sub":"注意对方攻击的格子","ls.b_safety.intro":"<p>如果你把棋子放在对方棋子能走到的地方，下一步它就会被<b>吃掉</b>。</p><p>在这个练习中，黑棋攻击的格子用<b>红色斜纹</b>标出。那里不能停留，请绕路收集★。</p><p class=\"note\">实战中，每走一步前都要养成问自己“那个格子受到攻击吗？”的习惯。</p>","ls.b_safety.goal":"只走安全的格子收集★。","ls.b_check.title":"将军","ls.b_check.sub":"攻击王","ls.b_check.intro":"<p><b>攻击对方王</b>的着法叫做<b>将军</b>。</p><p>被将军的一方必须在下一步保护自己的王。从这里开始适用完整规则：请为白方选择一步棋。</p>","ls.b_check.goal":"对黑方的王将军。","ls.b_check.hint":"红框是黑方的王。找一条能够到它的直线、斜线或跳法。","ls.b_check.why":"正确！{m} 将军。","ls.b_check.ng":"这步棋没有将军。答案之一：{m}","ls.b_escape.title":"摆脱将军","ls.b_escape.sub":"三种防守方法","ls.b_escape.intro":"<p>被将军时，必须做以下三件事之一：</p><p>① <b>走王</b>到安全的格子<br>② 在中间放一个棋子<b>挡住</b>（马的将军无法阻挡）<br>③ <b>吃掉</b>将军的棋子</p><p>不理会将军的着法是不允许的。想一想哪种防守最好。</p>","ls.b_escape.goal":"找出摆脱将军的最佳方法。","ls.b_escape.hint":"红框是你的王，粉框是正在将军的棋子。能吃掉它的话，吃掉最好。","ls.b_escape.why":"{m} 是最佳着法：既保住了王，又没有损失子力。","ls.b_mate.title":"将杀","ls.b_mate.sub":"这样就赢了！","ls.b_mate.intro":"<p>被将军的王<b>无法逃走、无法阻挡、也无法吃掉将军的棋子</b>时，就是<b>将杀</b>——将杀的一方<b>获胜</b>。</p><p>图中是“底线杀”：王被自己的兵挡住了退路。</p>","ls.b_mate.goal":"一步将杀。","ls.b_mate.hint":"红框是黑方的王。找一步让它无处可逃的将军。","ls.b_mate.why":"将杀！{m} 之后，黑方的王无处可逃。","ls.b_mate.ng":"这不是将杀。答案：{m}","ls.b_special.title":"特殊规则","ls.b_special.sub":"王车易位、吃过路兵、升变","ls.b_special.intro":"<p><b>王车易位</b>：如果王和车都从未动过，并且中间没有棋子，就可以把<b>王横向走两格</b>，车跳到王的另一侧——一步棋走两个棋子。被将军时或要经过受攻击的格子时不能易位。它能让你的王躲到安全的地方。</p><p><b>吃过路兵</b>：对方兵走两格、正好停在你的兵<b>旁边</b>时，你可以立刻像它只走了一格那样<b>斜着</b>吃掉它。</p><p><b>升变</b>：兵走到最后一行时变成后（或其他棋子）。</p><p class=\"note\">要王车易位，就把王横向走两格。</p>","ls.b_special.goal":"使用一种特殊规则（王车易位、吃过路兵、升变）。","ls.b_special.hint":"走金框里的棋子。","ls.b_special.why":"正确！{m}。","ls.b_special.ng":"答案是 {m}。王车易位是把王横向走两格；吃过路兵是斜着吃；升变时选后。","ls.b_draw.title":"和棋","ls.b_draw.sub":"小心逼和","ls.b_draw.intro":"<p>轮到走棋的一方<b>没有被将军，却没有合法着法</b>时，就是<b>逼和</b>——<b>和棋</b>。图中黑方的王没有被将军，但它能走的每个格子都受到攻击。</p><p>在优势局面下把对方逼和是常见的失误：要给王留一个格子，或者直接将杀。</p><p class=\"note\">此外，同一局面出现三次、50回合内无吃子也无兵移动、或双方子力都不足以将杀时，也是和棋。</p>","ls.b_draw.goal":"走出一步取胜的棋——不要逼和。","ls.b_draw.hint":"红框是黑方的王。你走完后，黑方还有棋可走吗（或者是将杀）？","ls.b_draw.why":"{m} 是最佳着法：不会逼和，还离胜利更近一步。"},
"ko":{"ls.desc":"규칙을 몰라도 괜찮아요. '처음 배우는 체스'에서 기물의 움직임부터 대국하는 방법까지, 판 위에서 직접 기물을 움직이며 익힐 수 있습니다. 그다음에는 '전술'에서 이기는 패턴을 배워 보세요(문제당 20점, 75점 이상 합격).","course.basics":"처음 배우는 체스","course.basics.sub":"규칙을 전혀 모르는 분을 위한 코스. 기물의 움직임 → 잡기 → 체크 → 체크메이트 → 특별 규칙 → 무승부 순서로, 판 위에서 기물을 움직이며 배웁니다.","course.tactics":"전술","course.tactics.sub":"규칙을 익혔다면 다음은 여기. 기물 이득, 포크, 메이트 모양 등 이기기 위한 생각법을 배웁니다.","course.graduate":"🎉 '처음 배우는 체스'를 수료했습니다! 이제 체스 규칙을 모두 익혔어요. 가장 순한 AI(Lv.1)와 실제로 대국해 보세요. 대국 중에 기물을 탭하면 움직일 수 있는 칸이 표시됩니다.","course.play":"AI(Lv.1)와 대국하기","dr.start":"기물을 탭(또는 드래그)해서 움직이고 ★을 모두 모으세요. 목표: {p}수.","dr.par":"(목표 {p}수)","dr.reset":"다시 하기","dr.progress":"{n}수째. ★이 {left}개 남았습니다.","dr.clear":"클리어!","dr.used":"{n}수에 모았습니다(목표 {p}수).","dr.tryPar":"'다시 하기'로 목표 수에 도전해 보세요.","dr.danger":"그 칸은 상대 기물이 노리고 있어 잡히고 맙니다. 빨간 줄무늬 칸에는 멈출 수 없습니다.","dr.more":"★ 3개는 목표 수 안에 클리어했다는 표시입니다.","ill.self":"그 수는 둘 수 없습니다. 움직이면 내 킹이 잡히는 상태가 됩니다.","ill.inCheck":"내 킹이 체크를 받고 있습니다. 먼저 킹을 지키세요.","ls.b_rook.title":"룩","ls.b_rook.sub":"가로・세로로 몇 칸이든","ls.b_rook.intro":"<p>체스는 <b>8×8 판</b>에서 둡니다. 백과 흑이 번갈아 기물 하나씩 움직이며, 백이 먼저 둡니다. <b>상대 킹을 꼼짝 못 하게 가두면 승리</b>(체크메이트)입니다. 먼저 기물마다 움직이는 법을 배워 봅시다.</p><p><b>룩</b>(성 모양)은 <b>가로나 세로로 똑바로</b>, 몇 칸이든 움직입니다. 다른 기물을 뛰어넘을 수는 없습니다.</p><p class=\"note\">룩을 움직여 판 위의 ★을 모두 모으세요. 점은 갈 수 있는 칸을 나타냅니다.</p>","ls.b_rook.goal":"룩으로 ★을 모두 모으자.","ls.b_bishop.title":"비숍","ls.b_bishop.sub":"대각선으로 몇 칸이든","ls.b_bishop.intro":"<p><b>비숍</b>(뾰족한 모자 모양)은 <b>대각선으로</b> 몇 칸이든 움직입니다.</p><p>대각선으로만 움직이기 때문에 비숍은 <b>항상 같은 색 칸에 머뭅니다</b>. 양쪽 모두 밝은 칸 비숍 하나, 어두운 칸 비숍 하나를 가지고 있습니다.</p>","ls.b_bishop.goal":"비숍으로 ★을 모두 모으자.","ls.b_queen.title":"퀸","ls.b_queen.sub":"가장 강한 기물","ls.b_queen.intro":"<p><b>퀸</b>(왕관 모양)은 룩과 비숍을 합친 기물로, <b>가로・세로・대각선</b>으로 몇 칸이든 움직입니다.</p><p>가장 강력한 기물이니 잃지 않도록 조심하세요.</p>","ls.b_queen.goal":"퀸으로 ★을 모두 모으자.","ls.b_king.title":"킹","ls.b_king.sub":"가장 중요한 기물","ls.b_king.intro":"<p><b>킹</b>(십자가가 달린 기물)은 <b>어느 방향으로든 한 칸</b> 움직입니다.</p><p>킹은 절대 잡혀서는 안 됩니다. 내 킹이 도망칠 수 없게 되면 집니다.</p>","ls.b_king.goal":"킹으로 ★을 모두 모으자.","ls.b_knight.title":"나이트","ls.b_knight.sub":"L자로 뛴다","ls.b_knight.intro":"<p><b>나이트</b>(말 모양)는 <b>L자 모양, 즉 한쪽으로 두 칸 가고 옆으로 한 칸</b> 움직입니다.</p><p>다른 기물을 <b>뛰어넘을 수 있는</b> 유일한 기물입니다. 뛸 때마다 서 있는 칸의 색도 바뀝니다.</p>","ls.b_knight.goal":"나이트로 ★을 모두 모으자.","ls.b_pawn.title":"폰","ls.b_pawn.sub":"앞으로 가고, 대각선으로 잡는다","ls.b_pawn.intro":"<p><b>폰</b>은 <b>앞으로 한 칸</b>씩 움직이며 뒤로는 갈 수 없습니다. 단, <b>처음 움직일 때는 두 칸</b>도 갈 수 있습니다.</p><p>잡을 때는 <b>대각선 앞 한 칸</b>으로 잡습니다. 바로 앞이 기물에 막히면 폰은 움직일 수 없습니다.</p><p>폰이 판의 <b>맨 끝</b>에 닿으면 퀸・룩・비숍・나이트 중 하나로 <b>프로모션</b>합니다. 거의 항상 퀸을 고릅니다.</p>","ls.b_pawn.goal":"폰으로 ★을 모두 모으자.","ls.b_capture.title":"기물 잡기","ls.b_capture.sub":"상대 기물이 있는 칸으로 간다","ls.b_capture.intro":"<p>내 기물이 갈 수 있는 칸에 상대 기물이 있으면, 그 칸으로 가서 <b>잡을</b> 수 있습니다. 잡힌 기물은 판에서 나갑니다.</p><p>기물에는 대략적인 가치가 있습니다: <b>폰 1・나이트 3・비숍 3・룩 5・퀸 9</b>. 가치 높은 기물을 더 많이 남기면 유리해집니다.</p><p class=\"note\">★ 위에 있는 흑 기물을 모두 잡으세요(흑 기물은 움직이지 않습니다).</p>","ls.b_capture.goal":"★ 위의 흑 기물을 모두 잡자.","ls.b_safety.title":"안전한 칸","ls.b_safety.sub":"상대가 노리는 칸에 주의","ls.b_safety.intro":"<p>상대 기물이 갈 수 있는 곳에 내 기물을 두면, 다음 수에 <b>잡히고</b> 맙니다.</p><p>이 연습에서는 흑 기물이 노리는 칸이 <b>빨간 줄무늬</b>로 표시됩니다. 그곳에는 멈출 수 없으니, 돌아가는 길을 찾아 ★을 모으세요.</p><p class=\"note\">실전에서도 매 수마다 \"그 칸은 공격받고 있나?\"를 확인하는 습관을 들이세요.</p>","ls.b_safety.goal":"안전한 칸만 지나서 ★을 모으자.","ls.b_check.title":"체크","ls.b_check.sub":"킹을 노린다","ls.b_check.intro":"<p><b>상대 킹을 공격하는</b> 수를 <b>체크</b>라고 합니다.</p><p>체크를 받은 쪽은 바로 다음 수에 킹을 지켜야 합니다. 여기서부터는 정식 규칙이 적용됩니다. 백의 수를 하나 고르세요.</p>","ls.b_check.goal":"흑 킹에게 체크를 걸자.","ls.b_check.hint":"빨간 테두리가 흑 킹입니다. 거기까지 닿는 선이나 뛰는 방법을 찾아보세요.","ls.b_check.why":"정답! {m}로 체크입니다.","ls.b_check.ng":"그 수는 체크가 아닙니다. 정답의 예: {m}","ls.b_escape.title":"체크에서 벗어나기","ls.b_escape.sub":"세 가지 방어법","ls.b_escape.intro":"<p>체크를 받으면 다음 세 가지 중 하나를 해야 합니다.</p><p>① <b>킹을 안전한 칸으로 옮긴다</b><br>② 사이에 기물을 놓아 <b>막는다</b>(나이트의 체크는 막을 수 없음)<br>③ 체크하는 기물을 <b>잡는다</b></p><p>체크를 무시하는 수는 둘 수 없습니다. 어떤 방어가 가장 좋은지 생각해 보세요.</p>","ls.b_escape.goal":"체크에서 벗어나는 가장 좋은 수를 찾자.","ls.b_escape.hint":"빨간 테두리가 내 킹, 분홍 테두리가 체크하는 기물입니다. 잡을 수 있다면 잡는 것이 가장 좋습니다.","ls.b_escape.why":"{m}가 최선입니다. 킹을 지키면서 기물도 잃지 않습니다.","ls.b_mate.title":"체크메이트","ls.b_mate.sub":"이걸로 승리!","ls.b_mate.intro":"<p>체크를 받은 킹이 <b>도망칠 수도, 막을 수도, 체크하는 기물을 잡을 수도 없으면</b> <b>체크메이트</b>이며, 메이트한 쪽이 <b>승리</b>합니다.</p><p>그림은 '백랭크 메이트'입니다. 킹의 도망길을 자기 폰이 막고 있습니다.</p>","ls.b_mate.goal":"한 수에 체크메이트하자.","ls.b_mate.hint":"빨간 테두리가 흑 킹입니다. 체크를 건 뒤 킹이 도망칠 칸이 남지 않는 수를 찾아보세요.","ls.b_mate.why":"체크메이트! {m} 후 흑 킹은 어디로도 도망칠 수 없습니다.","ls.b_mate.ng":"그 수로는 체크메이트가 되지 않습니다. 정답: {m}","ls.b_special.title":"특별 규칙","ls.b_special.sub":"캐슬링・앙파상・프로모션","ls.b_special.intro":"<p><b>캐슬링</b>: 킹과 룩이 한 번도 움직이지 않았고 사이에 기물이 없으면, <b>킹을 옆으로 두 칸</b> 옮기고 룩을 킹의 반대편으로 넘깁니다. 한 수에 기물 두 개를 움직이는 셈입니다. 체크를 받고 있을 때나 공격받는 칸을 지날 때는 할 수 없습니다. 킹을 안전한 곳으로 피신시키는 수입니다.</p><p><b>앙파상</b>: 상대 폰이 두 칸 전진해 내 폰 <b>바로 옆</b>에 온 직후에만, 한 칸 전진한 것처럼 <b>대각선으로</b> 잡을 수 있습니다.</p><p><b>프로모션</b>: 폰이 마지막 줄에 닿으면 퀸(또는 다른 기물)이 됩니다.</p><p class=\"note\">캐슬링은 킹을 옆으로 두 칸 움직이면 됩니다.</p>","ls.b_special.goal":"특별 규칙을 써 보자(캐슬링・앙파상・프로모션).","ls.b_special.hint":"금색 테두리의 기물을 움직이세요.","ls.b_special.why":"정답! {m}입니다.","ls.b_special.ng":"이번 정답은 {m}였습니다. 캐슬링은 킹을 옆으로 두 칸, 앙파상은 대각선으로 잡기, 프로모션은 퀸을 고릅니다.","ls.b_draw.title":"무승부","ls.b_draw.sub":"스테일메이트에 주의","ls.b_draw.intro":"<p>둘 차례인 쪽이 <b>체크는 아닌데 둘 수 있는 수가 하나도 없으면</b> <b>스테일메이트</b>로 <b>무승부</b>가 됩니다. 그림에서 흑 킹은 체크가 아니지만, 갈 수 있는 칸이 모두 공격받고 있습니다.</p><p>이기고 있을 때 상대를 스테일메이트로 만드는 것은 흔한 실수입니다. 킹에게 칸을 하나 남겨 주거나, 체크메이트하세요.</p><p class=\"note\">이 밖에도 같은 국면이 3번 나오거나, 50수 동안 잡기도 폰 이동도 없거나, 양쪽 모두 메이트할 기물이 부족하면 무승부입니다.</p>","ls.b_draw.goal":"스테일메이트 없이 승리로 이어지는 수를 두자.","ls.b_draw.hint":"빨간 테두리가 흑 킹입니다. 그 수 다음에 흑에게 둘 수 있는 수가 남는지(또는 체크메이트인지) 확인하세요.","ls.b_draw.why":"{m}가 최선입니다. 스테일메이트를 피하면서 승리에 다가갑니다."},
"es":{"ls.desc":"No hace falta saber las reglas. En «Ajedrez desde cero» aprenderás todo, desde cómo se mueven las piezas hasta cómo jugar una partida, moviendo piezas en el tablero. Después, aprende patrones para ganar en «Táctica» (20 puntos por problema; se aprueba con 75).","course.basics":"Ajedrez desde cero","course.basics.sub":"Para quien empieza de cero. Movimientos de las piezas → capturas → jaque → jaque mate → reglas especiales → tablas, aprendiendo a mover piezas en el tablero.","course.tactics":"Táctica","course.tactics.sub":"Cuando ya sepas las reglas: ganar material, ataques dobles, patrones de mate y otras formas de ganar.","course.graduate":"🎉 ¡Has terminado «Ajedrez desde cero»! Ya conoces todas las reglas del ajedrez. Prueba una partida de verdad contra la IA más suave (Lv.1). Durante la partida, toca una pieza para ver adónde puede moverse.","course.play":"Jugar contra la IA (Lv.1)","dr.start":"Toca (o arrastra) la pieza para moverla y recoge todas las ★. Objetivo: {p} jugadas.","dr.par":"(objetivo: {p} jugadas)","dr.reset":"Reiniciar","dr.progress":"Jugada {n}. Quedan {left} ★.","dr.clear":"¡Superado!","dr.used":"Has usado {n} jugadas (objetivo {p}).","dr.tryPar":"Pulsa «Reiniciar» para intentar lograr el objetivo.","dr.danger":"Esa casilla está atacada: te capturarían la pieza. No puedes detenerte en las casillas con rayas rojas.","dr.more":"Tres estrellas significan que superaste la fase con el número de jugadas objetivo.","ill.self":"No puedes hacer esa jugada: dejaría a tu propio rey expuesto a ser capturado.","ill.inCheck":"Tu rey está en jaque. Primero tienes que protegerlo.","ls.b_rook.title":"La torre","ls.b_rook.sub":"En línea recta, tan lejos como quiera","ls.b_rook.intro":"<p>El ajedrez se juega en un <b>tablero de 8×8</b>. Blancas y negras mueven una pieza por turnos; empiezan las blancas. <b>Ganas al atrapar al rey rival</b> (jaque mate). Primero, aprendamos cómo se mueve cada pieza.</p><p>La <b>torre</b> (el castillo) se mueve <b>en línea recta por filas y columnas</b>, tantas casillas como quiera. No puede saltar por encima de otras piezas.</p><p class=\"note\">Mueve la torre para recoger todas las ★ del tablero. Los puntos indican las casillas a las que puede llegar.</p>","ls.b_rook.goal":"Recoge todas las ★ con la torre.","ls.b_bishop.title":"El alfil","ls.b_bishop.sub":"En diagonal, las casillas que quiera","ls.b_bishop.intro":"<p>El <b>alfil</b> (el del gorro puntiagudo) se mueve <b>en diagonal</b>, tantas casillas como quiera.</p><p>Como solo se mueve en diagonal, un alfil <b>siempre se queda en casillas del mismo color</b>. Cada bando tiene un alfil de casillas claras y otro de casillas oscuras.</p>","ls.b_bishop.goal":"Recoge todas las ★ con el alfil.","ls.b_queen.title":"La dama","ls.b_queen.sub":"La pieza más fuerte","ls.b_queen.intro":"<p>La <b>dama</b> (la de la corona) combina la torre y el alfil: se mueve <b>en línea recta o en diagonal</b>, tantas casillas como quiera.</p><p>Es la pieza más poderosa, así que ten cuidado de no perderla.</p>","ls.b_queen.goal":"Recoge todas las ★ con la dama.","ls.b_king.title":"El rey","ls.b_king.sub":"La pieza más importante","ls.b_king.intro":"<p>El <b>rey</b> (el de la cruz) se mueve <b>una casilla en cualquier dirección</b>.</p><p>El rey nunca puede ser capturado. Si tu rey no puede escapar, pierdes.</p>","ls.b_king.goal":"Recoge todas las ★ con el rey.","ls.b_knight.title":"El caballo","ls.b_knight.sub":"Salta en forma de L","ls.b_knight.intro":"<p>El <b>caballo</b> se mueve en <b>forma de L: dos casillas en una dirección y una hacia un lado</b>.</p><p>Es la única pieza que puede <b>saltar por encima</b> de otras. En cada salto cambia también el color de su casilla.</p>","ls.b_knight.goal":"Recoge todas las ★ con el caballo.","ls.b_pawn.title":"El peón","ls.b_pawn.sub":"Avanza hacia delante, captura en diagonal","ls.b_pawn.intro":"<p>El <b>peón</b> avanza <b>una casilla hacia delante</b> y nunca retrocede, salvo que en su <b>primer movimiento puede avanzar dos casillas</b>.</p><p><b>Captura una casilla en diagonal hacia delante</b>. Si una pieza le bloquea justo delante, el peón no puede moverse.</p><p>Cuando un peón llega al <b>otro extremo</b> del tablero, se produce la <b>coronación</b>: se convierte en dama, torre, alfil o caballo (casi siempre en dama).</p>","ls.b_pawn.goal":"Recoge todas las ★ con el peón.","ls.b_capture.title":"Capturar","ls.b_capture.sub":"Muévete a la casilla de una pieza rival","ls.b_capture.intro":"<p>Si una pieza rival está en una casilla a la que tu pieza puede moverse, puedes ir allí y <b>capturarla</b>. Las piezas capturadas salen del tablero.</p><p>Las piezas tienen un valor aproximado: <b>peón 1, caballo 3, alfil 3, torre 5, dama 9</b>. Conservar más piezas valiosas te da ventaja.</p><p class=\"note\">Captura todas las piezas negras que están sobre una ★ (las piezas negras no se mueven).</p>","ls.b_capture.goal":"Captura todas las piezas negras que están sobre una ★.","ls.b_safety.title":"Casillas seguras","ls.b_safety.sub":"Fíjate en lo que ataca el rival","ls.b_safety.intro":"<p>Si colocas una pieza donde puede llegar una pieza rival, te la <b>capturarán</b> en la jugada siguiente.</p><p>En este ejercicio, las casillas que atacan las piezas negras aparecen con <b>rayas rojas</b>. No puedes detenerte en ellas, así que busca otro camino para recoger las ★.</p><p class=\"note\">En las partidas reales, acostúmbrate a preguntarte «¿está atacada esa casilla?» antes de cada jugada.</p>","ls.b_safety.goal":"Recoge las ★ pasando solo por casillas seguras.","ls.b_check.title":"Jaque","ls.b_check.sub":"Ataca al rey","ls.b_check.intro":"<p>Una jugada que <b>ataca al rey rival</b> se llama <b>jaque</b>.</p><p>El bando que está en jaque debe proteger a su rey en la jugada siguiente. A partir de aquí se aplican todas las reglas: elige una jugada para las blancas.</p>","ls.b_check.goal":"Da jaque al rey negro.","ls.b_check.hint":"El marco rojo es el rey negro. Busca una línea o un salto que llegue hasta él.","ls.b_check.why":"¡Correcto! {m} da jaque.","ls.b_check.ng":"Esa jugada no da jaque. Una respuesta posible: {m}","ls.b_escape.title":"Salir del jaque","ls.b_escape.sub":"Tres formas de defenderse","ls.b_escape.intro":"<p>Cuando estás en jaque, tienes que hacer una de estas tres cosas:</p><p>① <b>Mover el rey</b> a una casilla segura<br>② <b>Tapar</b> el jaque poniendo una pieza en medio (no se puede contra un caballo)<br>③ <b>Capturar</b> la pieza que da jaque</p><p>No se permiten jugadas que ignoren el jaque. Piensa cuál es la mejor defensa.</p>","ls.b_escape.goal":"Encuentra la mejor forma de salir del jaque.","ls.b_escape.hint":"El marco rojo es tu rey; el rosa, la pieza que da jaque. Si puedes capturarla, eso es lo mejor.","ls.b_escape.why":"{m} es lo mejor: salva al rey sin perder material.","ls.b_mate.title":"Jaque mate","ls.b_mate.sub":"¡Así se gana la partida!","ls.b_mate.intro":"<p>Cuando un rey en jaque <b>no puede apartarse, no se puede tapar el jaque y no se puede capturar la pieza que lo da</b>, es <b>jaque mate</b>, y el bando que lo ha dado <b>gana</b>.</p><p>El diagrama muestra un «mate del pasillo»: los propios peones del rey le cierran la salida.</p>","ls.b_mate.goal":"Da jaque mate en una jugada.","ls.b_mate.hint":"El marco rojo es el rey negro. Busca un jaque que no le deje ninguna casilla de escape.","ls.b_mate.why":"¡Jaque mate! Tras {m}, el rey negro no tiene adónde ir.","ls.b_mate.ng":"Eso no es jaque mate. La respuesta: {m}","ls.b_special.title":"Reglas especiales","ls.b_special.sub":"Enroque, captura al paso, coronación","ls.b_special.intro":"<p><b>Enroque</b>: si el rey y una torre no se han movido nunca y no hay nada entre ellos, mueve el <b>rey dos casillas hacia un lado</b>; la torre salta al otro lado del rey: dos piezas en una sola jugada. No se puede enrocar estando en jaque ni pasando por una casilla atacada. Sirve para poner a salvo a tu rey.</p><p><b>Captura al paso</b>: justo después de que un peón rival avance dos casillas y quede <b>al lado</b> de tu peón, puedes capturarlo <b>en diagonal</b> como si solo hubiera avanzado una.</p><p><b>Coronación</b>: un peón que llega a la última fila se convierte en dama (u otra pieza).</p><p class=\"note\">Para enrocar, mueve el rey dos casillas hacia un lado.</p>","ls.b_special.goal":"Usa una regla especial (enroque, captura al paso, coronación).","ls.b_special.hint":"Mueve la pieza del marco dorado.","ls.b_special.why":"¡Correcto! {m}.","ls.b_special.ng":"La respuesta era {m}. Para enrocar, mueve el rey dos casillas hacia un lado; la captura al paso se hace en diagonal; al coronar, elige dama.","ls.b_draw.title":"Tablas","ls.b_draw.sub":"Cuidado con el ahogado","ls.b_draw.intro":"<p>Si el bando al que le toca mover <b>no está en jaque pero no tiene ninguna jugada legal</b>, es <b>ahogado</b>: la partida termina en <b>tablas</b>. En el diagrama, el rey negro no está en jaque, pero todas las casillas a las que podría ir están atacadas.</p><p>Ahogar al rival cuando vas ganando es un error clásico: deja una casilla libre al rey, o da jaque mate.</p><p class=\"note\">También hay tablas por triple repetición de la posición, por 50 jugadas sin capturas ni movimientos de peón, o cuando ningún bando tiene material suficiente para dar mate.</p>","ls.b_draw.goal":"Haz una jugada ganadora, sin ahogar al rival.","ls.b_draw.hint":"El marco rojo es el rey negro. Después de tu jugada, ¿le queda alguna jugada a las negras (o es mate)?","ls.b_draw.why":"{m} es lo mejor: no hay ahogado y te acerca a la victoria."},
"fr":{"ls.desc":"Pas besoin de connaître les règles. « Débuter aux échecs » vous apprend tout, du déplacement des pièces jusqu'à la partie complète, en déplaçant les pièces sur l'échiquier. Ensuite, découvrez les schémas gagnants dans « Tactique » (20 points par problème, 75 pour réussir).","course.basics":"Débuter aux échecs","course.basics.sub":"Pour les grands débutants. Déplacements des pièces → prises → échec → échec et mat → règles spéciales → nulles, appris en déplaçant les pièces sur l'échiquier.","course.tactics":"Tactique","course.tactics.sub":"Une fois les règles connues : gagner du matériel, fourchettes, motifs de mat et autres façons de gagner.","course.graduate":"🎉 Vous avez terminé « Débuter aux échecs » : vous connaissez maintenant toutes les règles des échecs ! Essayez une vraie partie contre l'IA la plus douce (Lv.1). Pendant la partie, touchez une pièce pour voir où elle peut aller.","course.play":"Jouer contre l'IA (Lv.1)","dr.start":"Touchez (ou faites glisser) la pièce pour la déplacer et ramassez toutes les ★. Objectif : {p} coups.","dr.par":"(objectif : {p} coups)","dr.reset":"Recommencer","dr.progress":"Coup {n}. Encore {left} ★.","dr.clear":"Réussi !","dr.used":"Vous avez utilisé {n} coups (objectif {p}).","dr.tryPar":"Appuyez sur « Recommencer » pour tenter l'objectif.","dr.danger":"Cette case est attaquée : votre pièce serait prise. Vous ne pouvez pas vous arrêter sur les cases à rayures rouges.","dr.more":"Trois étoiles signifient que vous avez réussi l'étape dans le nombre de coups visé.","ill.self":"Ce coup est impossible : il laisserait votre propre roi exposé à la prise.","ill.inCheck":"Votre roi est en échec. Vous devez d'abord le protéger.","ls.b_rook.title":"La tour","ls.b_rook.sub":"Tout droit, aussi loin qu'elle veut","ls.b_rook.intro":"<p>Les échecs se jouent sur un <b>échiquier de 8×8 cases</b>. Les Blancs et les Noirs déplacent une pièce chacun leur tour ; les Blancs commencent. On <b>gagne en piégeant le roi adverse</b> (échec et mat). D'abord, apprenons comment se déplace chaque pièce.</p><p>La <b>tour</b> (le château) se déplace <b>en ligne droite sur les rangées et les colonnes</b>, d'autant de cases qu'elle veut. Elle ne peut pas sauter par-dessus les autres pièces.</p><p class=\"note\">Déplacez la tour pour ramasser toutes les ★ de l'échiquier. Les points indiquent les cases qu'elle peut atteindre.</p>","ls.b_rook.goal":"Ramassez toutes les ★ avec la tour.","ls.b_bishop.title":"Le fou","ls.b_bishop.sub":"En diagonale, d'autant de cases qu'il veut","ls.b_bishop.intro":"<p>Le <b>fou</b> (le chapeau pointu) se déplace <b>en diagonale</b>, d'autant de cases qu'il veut.</p><p>Comme il ne va qu'en diagonale, un fou <b>reste toujours sur la même couleur</b>. Chaque camp a un fou de cases claires et un fou de cases foncées.</p>","ls.b_bishop.goal":"Ramassez toutes les ★ avec le fou.","ls.b_queen.title":"La dame","ls.b_queen.sub":"La pièce la plus forte","ls.b_queen.intro":"<p>La <b>dame</b> (la couronne) combine la tour et le fou : elle se déplace <b>en ligne droite ou en diagonale</b>, d'autant de cases qu'elle veut.</p><p>C'est la pièce la plus puissante : faites attention à ne pas la perdre.</p>","ls.b_queen.goal":"Ramassez toutes les ★ avec la dame.","ls.b_king.title":"Le roi","ls.b_king.sub":"La pièce la plus importante","ls.b_king.intro":"<p>Le <b>roi</b> (celui avec la croix) se déplace <b>d'une case dans n'importe quelle direction</b>.</p><p>Le roi ne doit jamais être pris. Si votre roi ne peut plus s'échapper, vous perdez.</p>","ls.b_king.goal":"Ramassez toutes les ★ avec le roi.","ls.b_knight.title":"Le cavalier","ls.b_knight.sub":"Saute en forme de L","ls.b_knight.intro":"<p>Le <b>cavalier</b> (le cheval) se déplace en <b>forme de L : deux cases dans une direction, puis une case sur le côté</b>.</p><p>C'est la seule pièce qui peut <b>sauter par-dessus</b> les autres. À chaque saut, il change aussi de couleur de case.</p>","ls.b_knight.goal":"Ramassez toutes les ★ avec le cavalier.","ls.b_pawn.title":"Le pion","ls.b_pawn.sub":"Avance tout droit, prend en diagonale","ls.b_pawn.intro":"<p>Le <b>pion</b> avance <b>d'une case</b> et ne recule jamais — sauf qu'à son <b>premier coup, il peut avancer de deux cases</b>.</p><p>Il <b>prend une case en diagonale vers l'avant</b>. Un pion bloqué par une pièce juste devant lui ne peut pas bouger.</p><p>Quand un pion atteint <b>l'autre bout</b> de l'échiquier, c'est la <b>promotion</b> : il devient dame, tour, fou ou cavalier — presque toujours une dame.</p>","ls.b_pawn.goal":"Ramassez toutes les ★ avec le pion.","ls.b_capture.title":"Prendre","ls.b_capture.sub":"Allez sur la case d'une pièce adverse","ls.b_capture.intro":"<p>Si une pièce adverse se trouve sur une case où votre pièce peut aller, vous pouvez vous y rendre et la <b>prendre</b>. Les pièces prises quittent l'échiquier.</p><p>Les pièces ont une valeur approximative : <b>pion 1, cavalier 3, fou 3, tour 5, dame 9</b>. Garder plus de pièces de valeur vous donne l'avantage.</p><p class=\"note\">Prenez toutes les pièces noires posées sur une ★ (les pièces noires ne bougent pas).</p>","ls.b_capture.goal":"Prenez toutes les pièces noires posées sur une ★.","ls.b_safety.title":"Les cases sûres","ls.b_safety.sub":"Attention à ce que l'adversaire attaque","ls.b_safety.intro":"<p>Si vous placez une pièce là où une pièce adverse peut aller, elle sera <b>prise</b> au coup suivant.</p><p>Dans cet exercice, les cases attaquées par les pièces noires sont marquées de <b>rayures rouges</b>. Vous ne pouvez pas vous y arrêter : trouvez un détour pour ramasser les ★.</p><p class=\"note\">En partie, prenez l'habitude de vous demander « cette case est-elle attaquée ? » avant chaque coup.</p>","ls.b_safety.goal":"Ramassez les ★ en passant uniquement par des cases sûres.","ls.b_check.title":"L'échec","ls.b_check.sub":"Attaquer le roi","ls.b_check.intro":"<p>Un coup qui <b>attaque le roi adverse</b> s'appelle un <b>échec</b>.</p><p>Le camp en échec doit protéger son roi dès le coup suivant. À partir d'ici, toutes les règles s'appliquent : choisissez un coup pour les Blancs.</p>","ls.b_check.goal":"Mettez le roi noir en échec.","ls.b_check.hint":"Le cadre rouge est le roi noir. Cherchez une ligne ou un saut qui l'atteint.","ls.b_check.why":"Bravo ! {m} donne échec.","ls.b_check.ng":"Ce coup ne donne pas échec. Une solution : {m}","ls.b_escape.title":"Sortir de l'échec","ls.b_escape.sub":"Trois façons de se défendre","ls.b_escape.intro":"<p>Quand vous êtes en échec, vous devez faire l'une de ces trois choses :</p><p>① <b>Déplacer le roi</b> sur une case sûre<br>② <b>Parer</b> en plaçant une pièce entre les deux (impossible contre un cavalier)<br>③ <b>Prendre</b> la pièce qui donne échec</p><p>Les coups qui ignorent l'échec sont interdits. Réfléchissez à la meilleure défense.</p>","ls.b_escape.goal":"Trouvez la meilleure façon de sortir de l'échec.","ls.b_escape.hint":"Le cadre rouge est votre roi, le cadre rose la pièce qui donne échec. Si vous pouvez la prendre, c'est le mieux.","ls.b_escape.why":"{m} est le meilleur coup : il sauve le roi sans perdre de matériel.","ls.b_mate.title":"L'échec et mat","ls.b_mate.sub":"C'est ainsi qu'on gagne !","ls.b_mate.intro":"<p>Quand un roi en échec <b>ne peut ni fuir, ni être protégé par une pièce interposée, ni voir la pièce qui l'attaque être prise</b>, c'est <b>échec et mat</b> — et le camp qui l'a donné <b>gagne</b>.</p><p>Le diagramme montre un « mat du couloir » : les propres pions du roi lui bloquent la fuite.</p>","ls.b_mate.goal":"Matez en un coup.","ls.b_mate.hint":"Le cadre rouge est le roi noir. Trouvez un échec qui ne lui laisse aucune case de fuite.","ls.b_mate.why":"Échec et mat ! Après {m}, le roi noir n'a nulle part où aller.","ls.b_mate.ng":"Ce n'est pas échec et mat. La solution : {m}","ls.b_special.title":"Règles spéciales","ls.b_special.sub":"Roque, prise en passant, promotion","ls.b_special.intro":"<p><b>Le roque</b> : si le roi et une tour n'ont jamais bougé et que rien ne se trouve entre eux, déplacez le <b>roi de deux cases sur le côté</b> ; la tour saute de l'autre côté du roi — deux pièces en un seul coup. Interdit quand on est en échec ou si le roi traverse une case attaquée. Cela met votre roi à l'abri.</p><p><b>La prise en passant</b> : juste après qu'un pion adverse a avancé de deux cases et s'est arrêté <b>à côté</b> de votre pion, vous pouvez le prendre <b>en diagonale</b> comme s'il n'avait avancé que d'une case.</p><p><b>La promotion</b> : un pion qui atteint la dernière rangée devient une dame (ou une autre pièce).</p><p class=\"note\">Pour roquer, déplacez le roi de deux cases sur le côté.</p>","ls.b_special.goal":"Utilisez une règle spéciale (roque, prise en passant, promotion).","ls.b_special.hint":"Déplacez la pièce dans le cadre doré.","ls.b_special.why":"Bravo ! {m}.","ls.b_special.ng":"La solution était {m}. Pour roquer, déplacez le roi de deux cases sur le côté ; la prise en passant se fait en diagonale ; pour la promotion, choisissez la dame.","ls.b_draw.title":"Les nulles","ls.b_draw.sub":"Attention au pat","ls.b_draw.intro":"<p>Si le camp au trait <b>n'est pas en échec mais n'a aucun coup légal</b>, c'est le <b>pat</b> — la partie est <b>nulle</b>. Sur le diagramme, le roi noir n'est pas en échec, mais toutes les cases où il pourrait aller sont attaquées.</p><p>Faire pat son adversaire alors qu'on gagne est une erreur classique : laissez une case au roi, ou donnez échec et mat.</p><p class=\"note\">La partie est aussi nulle en cas de triple répétition, après 50 coups sans prise ni coup de pion, ou quand aucun camp n'a assez de matériel pour mater.</p>","ls.b_draw.goal":"Jouez un coup gagnant — sans faire pat.","ls.b_draw.hint":"Le cadre rouge est le roi noir. Après votre coup, les Noirs ont-ils encore un coup (ou est-ce mat) ?","ls.b_draw.why":"{m} est le meilleur coup : pas de pat, et vous vous rapprochez de la victoire."},
"pt":{"ls.desc":"Não precisa saber as regras. Em «Xadrez do zero» você aprende tudo, do movimento das peças até jogar uma partida, movendo as peças no tabuleiro. Depois, aprenda padrões para vencer em «Táticas» (20 pontos por problema, 75 para passar).","course.basics":"Xadrez do zero","course.basics.sub":"Para quem está começando do zero. Movimento das peças → capturas → xeque → xeque-mate → regras especiais → empates, aprendendo ao mover as peças no tabuleiro.","course.tactics":"Táticas","course.tactics.sub":"Depois de aprender as regras: ganhar material, garfos, padrões de mate e outras formas de vencer.","course.graduate":"🎉 Você concluiu «Xadrez do zero» — agora conhece todas as regras do xadrez! Experimente uma partida de verdade contra a IA mais fácil (Lv.1). Durante a partida, toque numa peça para ver para onde ela pode ir.","course.play":"Jogar contra a IA (Lv.1)","dr.start":"Toque (ou arraste) a peça para movê-la e pegue todas as ★. Meta: {p} lances.","dr.par":"(meta: {p} lances)","dr.reset":"Recomeçar","dr.progress":"Lance {n}. Faltam {left} ★.","dr.clear":"Concluído!","dr.used":"Você usou {n} lances (meta: {p}).","dr.tryPar":"Toque em «Recomeçar» para tentar bater a meta.","dr.danger":"Essa casa está atacada — sua peça seria capturada. Você não pode parar nas casas com listras vermelhas.","dr.more":"Três estrelas significam que você concluiu a fase dentro da meta de lances.","ill.self":"Você não pode jogar esse lance: ele deixaria seu próprio rei exposto à captura.","ill.inCheck":"Seu rei está em xeque. Primeiro, você precisa protegê-lo.","ls.b_rook.title":"A torre","ls.b_rook.sub":"Quantas casas quiser, em linha reta para a frente, para trás ou para os lados","ls.b_rook.intro":"<p>O xadrez é jogado num <b>tabuleiro de 8×8 casas</b>. Brancas e pretas se alternam movendo uma peça por vez; as brancas começam. Você <b>vence ao encurralar o rei adversário</b> (xeque-mate). Primeiro, vamos aprender como cada peça se move.</p><p>A <b>torre</b> (a peça em forma de castelo) anda <b>em linha reta, pelas filas e colunas</b>, quantas casas quiser. Ela não pode pular por cima de outras peças.</p><p class=\"note\">Mova a torre para pegar todas as ★ do tabuleiro. Os pontos mostram as casas aonde ela pode ir.</p>","ls.b_rook.goal":"Pegue todas as ★ com a torre.","ls.b_bishop.title":"O bispo","ls.b_bishop.sub":"Quantas casas quiser, na diagonal","ls.b_bishop.intro":"<p>O <b>bispo</b> (a peça com chapéu pontudo) anda <b>na diagonal</b>, quantas casas quiser.</p><p>Como só anda na diagonal, o bispo <b>fica sempre em casas da mesma cor</b>. Cada lado tem um bispo das casas claras e um das casas escuras.</p>","ls.b_bishop.goal":"Pegue todas as ★ com o bispo.","ls.b_queen.title":"A dama","ls.b_queen.sub":"A peça mais forte","ls.b_queen.intro":"<p>A <b>dama</b> (a peça com coroa) junta a torre e o bispo: anda <b>em linha reta ou na diagonal</b>, quantas casas quiser.</p><p>É a peça mais poderosa, então cuidado para não perdê-la.</p>","ls.b_queen.goal":"Pegue todas as ★ com a dama.","ls.b_king.title":"O rei","ls.b_king.sub":"A peça mais importante","ls.b_king.intro":"<p>O <b>rei</b> (a peça com a cruz) anda <b>uma casa em qualquer direção</b>.</p><p>O rei nunca pode ser capturado. Se o seu rei não tiver como escapar, você perde.</p>","ls.b_king.goal":"Pegue todas as ★ com o rei.","ls.b_knight.title":"O cavalo","ls.b_knight.sub":"Salta em L","ls.b_knight.intro":"<p>O <b>cavalo</b> anda em <b>L: duas casas numa direção e uma para o lado</b>.</p><p>É a única peça que pode <b>pular por cima</b> das outras. A cada salto, ele também muda a cor da casa em que está.</p>","ls.b_knight.goal":"Pegue todas as ★ com o cavalo.","ls.b_pawn.title":"O peão","ls.b_pawn.sub":"Anda para a frente, captura na diagonal","ls.b_pawn.intro":"<p>O <b>peão</b> anda <b>uma casa para a frente</b> e nunca para trás — mas, no <b>seu primeiro lance, pode andar duas casas</b>.</p><p>Ele <b>captura uma casa na diagonal, para a frente</b>. Um peão com uma peça bem à sua frente não pode andar.</p><p>Quando um peão chega à <b>última fila</b> do tabuleiro, ele é <b>promovido</b> a dama, torre, bispo ou cavalo — quase sempre a dama.</p>","ls.b_pawn.goal":"Pegue todas as ★ com o peão.","ls.b_capture.title":"Capturar","ls.b_capture.sub":"Vá para a casa de uma peça adversária","ls.b_capture.intro":"<p>Se uma peça adversária está numa casa aonde sua peça pode ir, você pode ir até lá e <b>capturá-la</b>. As peças capturadas saem do tabuleiro.</p><p>As peças têm valores aproximados: <b>peão 1, cavalo 3, bispo 3, torre 5, dama 9</b>. Manter as peças mais valiosas dá vantagem.</p><p class=\"note\">Capture todas as peças pretas que estão sobre uma ★ (as peças pretas não se movem).</p>","ls.b_capture.goal":"Capture todas as peças pretas sobre as ★.","ls.b_safety.title":"Casas seguras","ls.b_safety.sub":"Veja o que o adversário ataca","ls.b_safety.intro":"<p>Se você colocar uma peça numa casa aonde uma peça adversária pode ir, ela será <b>capturada</b> no lance seguinte.</p><p>Neste exercício, as casas atacadas pelas peças pretas aparecem com <b>listras vermelhas</b>. Você não pode parar nelas, então encontre outro caminho para pegar as ★.</p><p class=\"note\">Nas partidas de verdade, crie o hábito de perguntar «essa casa está atacada?» antes de cada lance.</p>","ls.b_safety.goal":"Pegue as ★ passando só por casas seguras.","ls.b_check.title":"Xeque","ls.b_check.sub":"Ataque o rei","ls.b_check.intro":"<p>Um lance que <b>ataca o rei adversário</b> se chama <b>xeque</b>.</p><p>Quem está em xeque precisa proteger o rei logo no lance seguinte. A partir daqui valem as regras completas: escolha um lance para as brancas.</p>","ls.b_check.goal":"Dê xeque no rei preto.","ls.b_check.hint":"A moldura vermelha é o rei preto. Procure uma linha ou um salto que chegue até ele.","ls.b_check.why":"Correto! {m} dá xeque.","ls.b_check.ng":"Esse lance não dá xeque. Uma resposta: {m}","ls.b_escape.title":"Sair do xeque","ls.b_escape.sub":"Três formas de defesa","ls.b_escape.intro":"<p>Quando você está em xeque, precisa fazer uma destas três coisas:</p><p>① <b>Mover o rei</b> para uma casa segura<br>② <b>Bloquear</b>, colocando uma peça no meio (não funciona contra o cavalo)<br>③ <b>Capturar</b> a peça que dá xeque</p><p>Lances que ignoram o xeque não são permitidos. Pense em qual defesa é a melhor.</p>","ls.b_escape.goal":"Encontre a melhor forma de sair do xeque.","ls.b_escape.hint":"A moldura vermelha é o seu rei; a rosa, a peça que dá xeque. Se puder capturá-la, essa é a melhor opção.","ls.b_escape.why":"{m} é o melhor: salva o rei sem perder material.","ls.b_mate.title":"Xeque-mate","ls.b_mate.sub":"Assim se vence a partida!","ls.b_mate.intro":"<p>Quando um rei em xeque <b>não pode fugir, não pode ser protegido por uma peça no meio e a peça que dá xeque não pode ser capturada</b>, é <b>xeque-mate</b> — e quem deu o mate <b>vence</b>.</p><p>O diagrama mostra um «mate do corredor»: os próprios peões do rei bloqueiam a fuga.</p>","ls.b_mate.goal":"Dê xeque-mate em um lance.","ls.b_mate.hint":"A moldura vermelha é o rei preto. Encontre um xeque que não lhe deixe nenhuma casa de fuga.","ls.b_mate.why":"Xeque-mate! Depois de {m}, o rei preto não tem para onde ir.","ls.b_mate.ng":"Isso não é xeque-mate. A resposta: {m}","ls.b_special.title":"Regras especiais","ls.b_special.sub":"Roque, en passant, promoção","ls.b_special.intro":"<p><b>Roque</b>: se o rei e uma torre nunca se moveram e não há nada entre eles, mova o <b>rei duas casas para o lado</b>; a torre salta para o outro lado do rei — duas peças num só lance. Não é permitido estando em xeque nem passando por uma casa atacada. Serve para deixar o rei em segurança.</p><p><b>En passant</b>: logo depois que um peão adversário anda duas casas e para <b>ao lado</b> do seu peão, você pode capturá-lo <b>na diagonal</b>, como se ele tivesse andado só uma casa.</p><p><b>Promoção</b>: um peão que chega à última fila vira dama (ou outra peça).</p><p class=\"note\">Para fazer o roque, mova o rei duas casas para o lado.</p>","ls.b_special.goal":"Use uma regra especial (roque, en passant, promoção).","ls.b_special.hint":"Mova a peça da moldura dourada.","ls.b_special.why":"Correto! {m}.","ls.b_special.ng":"A resposta era {m}. Para o roque, mova o rei duas casas para o lado; o en passant captura na diagonal; na promoção, escolha a dama.","ls.b_draw.title":"Empates","ls.b_draw.sub":"Cuidado com o afogamento","ls.b_draw.intro":"<p>Se quem joga <b>não está em xeque, mas não tem nenhum lance legal</b>, é <b>afogamento</b> — um <b>empate</b>. No diagrama, o rei preto não está em xeque, mas todas as casas para onde poderia ir estão atacadas.</p><p>Afogar o adversário quando você está ganhando é um erro clássico: deixe uma casa livre para o rei ou dê xeque-mate.</p><p class=\"note\">A partida também termina empatada quando a mesma posição se repete três vezes, após 50 lances sem captura nem lance de peão, ou quando nenhum lado tem material para dar mate.</p>","ls.b_draw.goal":"Faça um lance vencedor — sem afogar.","ls.b_draw.hint":"A moldura vermelha é o rei preto. Depois do seu lance, as pretas ainda têm algum lance (ou é mate)?","ls.b_draw.why":"{m} é o melhor: não há afogamento e você se aproxima da vitória."},
"de":{"ls.desc":"Du musst die Regeln nicht kennen. In „Schach von Anfang an“ lernst du alles – von den Zügen der Figuren bis zur ganzen Partie –, indem du Figuren auf dem Brett ziehst. Danach lernst du in „Taktik“ Gewinnmuster (20 Punkte pro Aufgabe, bestanden ab 75).","course.basics":"Schach von Anfang an","course.basics.sub":"Für absolute Anfänger. Zugregeln → Schlagen → Schach → Schachmatt → Sonderregeln → Remis – gelernt, indem du Figuren auf dem Brett ziehst.","course.tactics":"Taktik","course.tactics.sub":"Wenn du die Regeln kennst: Material gewinnen, Gabeln, Mattbilder und andere Wege zum Sieg.","course.graduate":"🎉 Du hast „Schach von Anfang an“ abgeschlossen – jetzt kennst du alle Schachregeln! Spiel eine echte Partie gegen die sanfteste KI (Lv.1). Tippe während der Partie auf eine Figur, um zu sehen, wohin sie ziehen kann.","course.play":"Gegen die KI spielen (Lv.1)","dr.start":"Tippe auf die Figur (oder ziehe sie), um sie zu bewegen, und sammle alle ★. Ziel: {p} Züge.","dr.par":"(Ziel: {p} Züge)","dr.reset":"Neu starten","dr.progress":"Zug {n}. Noch {left} ★.","dr.clear":"Geschafft!","dr.used":"Du hast {n} Züge gebraucht (Ziel: {p}).","dr.tryPar":"Drücke „Neu starten“, um das Ziel zu schaffen.","dr.danger":"Dieses Feld wird angegriffen – deine Figur würde geschlagen. Auf den rot gestreiften Feldern darfst du nicht stehen bleiben.","dr.more":"Drei Sterne bedeuten, dass du die Stufe mit der Zielzahl an Zügen geschafft hast.","ill.self":"Dieser Zug geht nicht: Dein eigener König könnte dann geschlagen werden.","ill.inCheck":"Dein König steht im Schach. Du musst ihn zuerst schützen.","ls.b_rook.title":"Der Turm","ls.b_rook.sub":"Beliebig weit geradeaus: vor, zurück oder zur Seite","ls.b_rook.intro":"<p>Schach wird auf einem <b>Brett mit 8×8 Feldern</b> gespielt. Weiß und Schwarz ziehen abwechselnd je eine Figur; Weiß beginnt. Du <b>gewinnst, wenn du den gegnerischen König fängst</b> (Schachmatt). Lernen wir zuerst, wie jede Figur zieht.</p><p>Der <b>Turm</b> (die Figur, die wie eine Burg aussieht) zieht <b>gerade entlang der Reihen und Linien</b>, beliebig viele Felder. Er kann nicht über andere Figuren springen.</p><p class=\"note\">Ziehe den Turm und sammle alle ★ auf dem Brett. Die Punkte zeigen die Felder, die er erreichen kann.</p>","ls.b_rook.goal":"Sammle alle ★ mit dem Turm.","ls.b_bishop.title":"Der Läufer","ls.b_bishop.sub":"Beliebig weit diagonal","ls.b_bishop.intro":"<p>Der <b>Läufer</b> (die Figur mit dem spitzen Hut) zieht <b>diagonal</b>, beliebig viele Felder.</p><p>Weil er nur diagonal zieht, <b>bleibt ein Läufer immer auf derselben Farbe</b>. Jede Seite hat einen weißfeldrigen und einen schwarzfeldrigen Läufer.</p>","ls.b_bishop.goal":"Sammle alle ★ mit dem Läufer.","ls.b_queen.title":"Die Dame","ls.b_queen.sub":"Die stärkste Figur","ls.b_queen.intro":"<p>Die <b>Dame</b> (die Figur mit der Krone) vereint Turm und Läufer: Sie zieht <b>gerade oder diagonal</b>, beliebig viele Felder.</p><p>Sie ist die stärkste Figur – pass gut auf, dass du sie nicht verlierst.</p>","ls.b_queen.goal":"Sammle alle ★ mit der Dame.","ls.b_king.title":"Der König","ls.b_king.sub":"Die wichtigste Figur","ls.b_king.intro":"<p>Der <b>König</b> (die Figur mit dem Kreuz) zieht <b>ein Feld in jede Richtung</b>.</p><p>Der König darf niemals geschlagen werden. Kann dein König nicht mehr entkommen, hast du verloren.</p>","ls.b_king.goal":"Sammle alle ★ mit dem König.","ls.b_knight.title":"Der Springer","ls.b_knight.sub":"Springt im L","ls.b_knight.intro":"<p>Der <b>Springer</b> (das Pferd) zieht im <b>L: zwei Felder in eine Richtung und ein Feld zur Seite</b>.</p><p>Er ist die einzige Figur, die <b>über andere Figuren springen</b> kann. Bei jedem Sprung wechselt er außerdem die Farbe seines Feldes.</p>","ls.b_knight.goal":"Sammle alle ★ mit dem Springer.","ls.b_pawn.title":"Der Bauer","ls.b_pawn.sub":"Zieht vorwärts, schlägt schräg","ls.b_pawn.intro":"<p>Der <b>Bauer</b> zieht <b>ein Feld vorwärts</b> und nie zurück – nur bei <b>seinem ersten Zug darf er zwei Felder</b> ziehen.</p><p>Er <b>schlägt ein Feld schräg nach vorn</b>. Steht direkt vor ihm eine Figur, kann der Bauer nicht ziehen.</p><p>Erreicht ein Bauer das <b>andere Ende</b> des Bretts, wird er <b>umgewandelt</b> – in eine Dame, einen Turm, Läufer oder Springer, fast immer in eine Dame.</p>","ls.b_pawn.goal":"Sammle alle ★ mit dem Bauern.","ls.b_capture.title":"Schlagen","ls.b_capture.sub":"Zieh auf das Feld einer gegnerischen Figur","ls.b_capture.intro":"<p>Steht eine gegnerische Figur auf einem Feld, das deine Figur erreichen kann, darfst du dorthin ziehen und sie <b>schlagen</b>. Geschlagene Figuren verlassen das Brett.</p><p>Figuren haben ungefähre Werte: <b>Bauer 1, Springer 3, Läufer 3, Turm 5, Dame 9</b>. Wer die wertvolleren Figuren behält, ist im Vorteil.</p><p class=\"note\">Schlage alle schwarzen Figuren, die auf einem ★ stehen (die schwarzen Figuren ziehen nicht).</p>","ls.b_capture.goal":"Schlage alle schwarzen Figuren auf den ★.","ls.b_safety.title":"Sichere Felder","ls.b_safety.sub":"Achte darauf, was der Gegner angreift","ls.b_safety.intro":"<p>Stellst du eine Figur auf ein Feld, das eine gegnerische Figur erreichen kann, wird sie im nächsten Zug <b>geschlagen</b>.</p><p>In dieser Übung sind die Felder, die die schwarzen Figuren angreifen, <b>rot gestreift</b>. Dort darfst du nicht stehen bleiben – finde einen Umweg, um die ★ zu sammeln.</p><p class=\"note\">Gewöhne dir in echten Partien an, vor jedem Zug zu fragen: „Wird dieses Feld angegriffen?“</p>","ls.b_safety.goal":"Sammle die ★ nur über sichere Felder.","ls.b_check.title":"Schach","ls.b_check.sub":"Den König angreifen","ls.b_check.intro":"<p>Ein Zug, der <b>den gegnerischen König angreift</b>, heißt <b>Schach</b>.</p><p>Wer im Schach steht, muss seinen König gleich im nächsten Zug schützen. Ab hier gelten die vollständigen Regeln: Wähle einen Zug für Weiß.</p>","ls.b_check.goal":"Biete dem schwarzen König Schach.","ls.b_check.hint":"Der rote Rahmen ist der schwarze König. Suche eine Linie oder einen Sprung, der ihn erreicht.","ls.b_check.why":"Richtig! {m} bietet Schach.","ls.b_check.ng":"Dieser Zug bietet kein Schach. Eine Lösung: {m}","ls.b_escape.title":"Raus aus dem Schach","ls.b_escape.sub":"Drei Arten der Verteidigung","ls.b_escape.intro":"<p>Stehst du im Schach, musst du eins von drei Dingen tun:</p><p>① <b>Den König ziehen</b> – auf ein sicheres Feld<br>② <b>Dazwischenziehen</b>, also eine Figur dazwischenstellen (geht nicht gegen einen Springer)<br>③ Die Schach gebende Figur <b>schlagen</b></p><p>Züge, die das Schach ignorieren, sind nicht erlaubt. Überlege, welche Verteidigung die beste ist.</p>","ls.b_escape.goal":"Finde den besten Weg aus dem Schach.","ls.b_escape.hint":"Der rote Rahmen ist dein König, der rosa Rahmen die Schach gebende Figur. Wenn du sie schlagen kannst, ist das am besten.","ls.b_escape.why":"{m} ist am besten: Der König ist gerettet, ohne Material zu verlieren.","ls.b_mate.title":"Schachmatt","ls.b_mate.sub":"Damit gewinnst du die Partie!","ls.b_mate.intro":"<p>Kann ein König im Schach <b>weder wegziehen noch durch eine Figur geschützt werden, und kann die Schach gebende Figur nicht geschlagen werden</b>, ist das <b>Schachmatt</b> – und wer mattgesetzt hat, <b>gewinnt</b>.</p><p>Das Diagramm zeigt ein „Grundreihenmatt“: Die eigenen Bauern des Königs versperren ihm die Flucht.</p>","ls.b_mate.goal":"Setze in einem Zug matt.","ls.b_mate.hint":"Der rote Rahmen ist der schwarze König. Finde ein Schach, das ihm kein Fluchtfeld lässt.","ls.b_mate.why":"Schachmatt! Nach {m} kann der schwarze König nirgendwohin.","ls.b_mate.ng":"Das ist kein Schachmatt. Die Lösung: {m}","ls.b_special.title":"Sonderregeln","ls.b_special.sub":"Rochade, en passant, Umwandlung","ls.b_special.intro":"<p><b>Rochade</b>: Haben König und Turm noch nie gezogen und steht nichts zwischen ihnen, ziehst du den <b>König zwei Felder zur Seite</b>; der Turm springt auf die andere Seite des Königs – zwei Figuren in einem Zug. Nicht erlaubt, wenn du im Schach stehst oder der König über ein angegriffenes Feld zieht. So bringst du deinen König in Sicherheit.</p><p><b>En passant</b>: Direkt nachdem ein gegnerischer Bauer zwei Felder vorgerückt ist und <b>neben</b> deinem Bauern steht, darfst du ihn <b>schräg</b> schlagen, als wäre er nur ein Feld gezogen.</p><p><b>Umwandlung</b>: Ein Bauer, der die letzte Reihe erreicht, wird zur Dame (oder einer anderen Figur).</p><p class=\"note\">Zum Rochieren ziehst du den König zwei Felder zur Seite.</p>","ls.b_special.goal":"Nutze eine Sonderregel (Rochade, en passant, Umwandlung).","ls.b_special.hint":"Ziehe die Figur im goldenen Rahmen.","ls.b_special.why":"Richtig! {m}.","ls.b_special.ng":"Die Lösung war {m}. Rochade: König zwei Felder zur Seite; en passant wird schräg geschlagen; umgewandelt wird in eine Dame.","ls.b_draw.title":"Remis","ls.b_draw.sub":"Vorsicht vor dem Patt","ls.b_draw.intro":"<p>Steht die Seite am Zug <b>nicht im Schach, hat aber keinen legalen Zug</b>, ist das <b>Patt</b> – ein <b>Remis</b> (unentschieden). Im Diagramm steht der schwarze König nicht im Schach, doch jedes Feld, auf das er ziehen könnte, wird angegriffen.</p><p>Den Gegner patt zu setzen, obwohl du gewinnst, ist ein klassischer Fehler: Lass dem König ein Feld frei oder setze ihn matt.</p><p class=\"note\">Remis ist es auch bei dreifacher Stellungswiederholung, nach 50 Zügen ohne Schlagen oder Bauernzug oder wenn keine Seite genug Material zum Mattsetzen hat.</p>","ls.b_draw.goal":"Spiel einen Gewinnzug – ohne Patt.","ls.b_draw.hint":"Der rote Rahmen ist der schwarze König. Hat Schwarz nach deinem Zug noch einen Zug (oder ist es matt)?","ls.b_draw.why":"{m} ist am besten: kein Patt, und du kommst dem Sieg näher."},
"hi":{"ls.desc":"नियम पता न हों तो भी कोई बात नहीं। \"शतरंज शून्य से\" में मोहरों की चाल से लेकर पूरा खेल खेलने तक सब कुछ, बोर्ड पर मोहरे चलाते हुए सीखिए। फिर \"टैक्टिक्स\" में जीतने के पैटर्न सीखिए (हर प्रश्न 20 अंक, 75 पर उत्तीर्ण)।","course.basics":"शतरंज शून्य से","course.basics.sub":"बिल्कुल नए खिलाड़ियों के लिए। मोहरों की चाल → मारना → शह → शह-मात → विशेष नियम → बराबरी, बोर्ड पर मोहरे चलाकर सीखिए।","course.tactics":"टैक्टिक्स","course.tactics.sub":"नियम सीखने के बाद: मोहरे जीतना, फ़ोर्क, मात के पैटर्न और जीतने के दूसरे तरीके।","course.graduate":"🎉 आपने \"शतरंज शून्य से\" पूरा कर लिया — अब आप शतरंज के सारे नियम जानते हैं! सबसे आसान AI (Lv.1) से असली खेल खेलकर देखिए। खेल के दौरान किसी मोहरे पर टैप करें, तो दिखेगा कि वह कहाँ जा सकता है।","course.play":"AI (Lv.1) से खेलें","dr.start":"मोहरे को चलाने के लिए टैप (या ड्रैग) करें और सारे ★ इकट्ठा करें। लक्ष्य: {p} चालें।","dr.par":"(लक्ष्य: {p} चालें)","dr.reset":"फिर से शुरू","dr.progress":"चाल {n}। {left} ★ बाकी।","dr.clear":"पूरा हुआ!","dr.used":"आपने {n} चालें लीं (लक्ष्य {p})।","dr.tryPar":"लक्ष्य पाने के लिए \"फिर से शुरू\" दबाएँ।","dr.danger":"उस खाने पर हमला है — आपका मोहरा मारा जाएगा। लाल धारियों वाले खानों पर आप रुक नहीं सकते।","dr.more":"तीन सितारों का मतलब है कि आपने लक्ष्य जितनी चालों में यह स्तर पूरा किया।","ill.self":"यह चाल नहीं चल सकते: इससे आपका अपना राजा मारे जाने के लिए खुला रह जाएगा।","ill.inCheck":"आपके राजा पर शह है। पहले उसे बचाना ज़रूरी है।","ls.b_rook.title":"हाथी","ls.b_rook.sub":"सीधा आगे, पीछे या बगल में, कितनी भी दूर","ls.b_rook.intro":"<p>शतरंज <b>8×8 खानों</b> वाले बोर्ड पर खेला जाता है। सफ़ेद और काला बारी-बारी एक-एक मोहरा चलते हैं; पहले सफ़ेद चलता है। <b>विरोधी राजा को घेर लेने पर आप जीतते हैं</b> (शह-मात)। पहले सीखते हैं कि हर मोहरा कैसे चलता है।</p><p><b>हाथी</b> (किले जैसा दिखने वाला मोहरा) <b>सीधी और आड़ी रेखाओं पर</b> कितने भी खाने चलता है। यह दूसरे मोहरों के ऊपर से नहीं कूद सकता।</p><p class=\"note\">हाथी चलाकर बोर्ड के सारे ★ इकट्ठा करें। बिंदु वाले खाने वे हैं जहाँ यह जा सकता है।</p>","ls.b_rook.goal":"हाथी से सारे ★ इकट्ठा करें।","ls.b_bishop.title":"ऊँट","ls.b_bishop.sub":"तिरछा, कितनी भी दूर","ls.b_bishop.intro":"<p><b>ऊँट</b> (नुकीली टोपी वाला मोहरा) <b>तिरछा</b> कितने भी खाने चलता है।</p><p>क्योंकि यह सिर्फ़ तिरछा चलता है, ऊँट <b>हमेशा एक ही रंग के खानों पर रहता है</b>। हर पक्ष के पास एक सफ़ेद खानों वाला और एक काले खानों वाला ऊँट होता है।</p>","ls.b_bishop.goal":"ऊँट से सारे ★ इकट्ठा करें।","ls.b_queen.title":"वज़ीर","ls.b_queen.sub":"सबसे ताकतवर मोहरा","ls.b_queen.intro":"<p><b>वज़ीर</b> (मुकुट वाला मोहरा) हाथी और ऊँट दोनों की चाल चलता है: <b>सीधा या तिरछा</b>, कितने भी खाने।</p><p>यह सबसे ताकतवर मोहरा है, इसलिए ध्यान रखें कि यह मारा न जाए।</p>","ls.b_queen.goal":"वज़ीर से सारे ★ इकट्ठा करें।","ls.b_king.title":"राजा","ls.b_king.sub":"सबसे ज़रूरी मोहरा","ls.b_king.intro":"<p><b>राजा</b> (क्रॉस वाला मोहरा) <b>किसी भी दिशा में एक खाना</b> चलता है।</p><p>राजा कभी मारा नहीं जाना चाहिए। अगर आपका राजा बच न सके, तो आप हार जाते हैं।</p>","ls.b_king.goal":"राजा से सारे ★ इकट्ठा करें।","ls.b_knight.title":"घोड़ा","ls.b_knight.sub":"L आकार में कूदता है","ls.b_knight.intro":"<p><b>घोड़ा</b> <b>L आकार में चलता है: एक दिशा में दो खाने और फिर एक खाना बगल में</b>।</p><p>यही अकेला मोहरा है जो दूसरे मोहरों के <b>ऊपर से कूद</b> सकता है। हर छलाँग में इसके खाने का रंग भी बदल जाता है।</p>","ls.b_knight.goal":"घोड़े से सारे ★ इकट्ठा करें।","ls.b_pawn.title":"प्यादा","ls.b_pawn.sub":"आगे चलता है, तिरछा मारता है","ls.b_pawn.intro":"<p><b>प्यादा</b> <b>एक खाना आगे</b> चलता है और कभी पीछे नहीं जाता — पर <b>अपनी पहली चाल में यह दो खाने</b> चल सकता है।</p><p>यह <b>तिरछा आगे एक खाने पर मारता है</b>। अगर ठीक सामने कोई मोहरा हो, तो प्यादा आगे नहीं बढ़ सकता।</p><p>जब प्यादा बोर्ड के <b>आखिरी छोर</b> पर पहुँचता है, तो उसका <b>प्रमोशन</b> होता है — वह वज़ीर, हाथी, ऊँट या घोड़ा बन जाता है, लगभग हमेशा वज़ीर।</p>","ls.b_pawn.goal":"प्यादे से सारे ★ इकट्ठा करें।","ls.b_capture.title":"मारना","ls.b_capture.sub":"विरोधी मोहरे के खाने पर जाइए","ls.b_capture.intro":"<p>अगर विरोधी का मोहरा ऐसे खाने पर है जहाँ आपका मोहरा जा सकता है, तो आप वहाँ जाकर उसे <b>मार</b> सकते हैं। मारे गए मोहरे बोर्ड से हट जाते हैं।</p><p>मोहरों का लगभग मूल्य: <b>प्यादा 1, घोड़ा 3, ऊँट 3, हाथी 5, वज़ीर 9</b>। ज़्यादा मूल्यवान मोहरे बचाकर रखने से फ़ायदा मिलता है।</p><p class=\"note\">★ पर खड़े सारे काले मोहरे मारिए (काले मोहरे नहीं चलते)।</p>","ls.b_capture.goal":"★ पर खड़े सारे काले मोहरे मारें।","ls.b_safety.title":"सुरक्षित खाने","ls.b_safety.sub":"देखिए विरोधी किस पर हमला कर रहा है","ls.b_safety.intro":"<p>अगर आप मोहरा ऐसे खाने पर रखें जहाँ विरोधी का मोहरा जा सकता है, तो अगली चाल में वह <b>मारा जाएगा</b>।</p><p>इस अभ्यास में काले मोहरों के हमले वाले खाने <b>लाल धारियों</b> से दिखाए गए हैं। वहाँ आप रुक नहीं सकते, इसलिए घूमकर रास्ता ढूँढिए और ★ इकट्ठा कीजिए।</p><p class=\"note\">असली खेल में भी हर चाल से पहले यह पूछने की आदत डालिए: \"क्या उस खाने पर हमला है?\"</p>","ls.b_safety.goal":"सिर्फ़ सुरक्षित खानों से होकर ★ इकट्ठा करें।","ls.b_check.title":"शह","ls.b_check.sub":"राजा पर हमला","ls.b_check.intro":"<p>जो चाल <b>विरोधी राजा पर हमला करे</b>, उसे <b>शह</b> (चेक) कहते हैं।</p><p>जिस पर शह हो, उसे ठीक अगली चाल में अपना राजा बचाना होता है। यहाँ से पूरे नियम लागू हैं: सफ़ेद के लिए एक चाल चुनिए।</p>","ls.b_check.goal":"काले राजा को शह दें।","ls.b_check.hint":"लाल फ्रेम काला राजा है। ऐसी रेखा या छलाँग ढूँढिए जो उस तक पहुँचे।","ls.b_check.why":"सही! {m} से शह होती है।","ls.b_check.ng":"इस चाल से शह नहीं होती। एक उत्तर: {m}","ls.b_escape.title":"शह से बचना","ls.b_escape.sub":"बचाव के तीन तरीके","ls.b_escape.intro":"<p>जब आप पर शह हो, तो इन तीन में से एक करना ही होगा:</p><p>① <b>राजा को हटाइए</b> (किसी सुरक्षित खाने पर)<br>② बीच में कोई मोहरा रखकर <b>रोकिए</b> (घोड़े की शह पर यह नहीं चलता)<br>③ शह देने वाले मोहरे को <b>मारिए</b></p><p>शह को अनदेखा करने वाली चालें मना हैं। सोचिए कि सबसे अच्छा बचाव कौन-सा है।</p>","ls.b_escape.goal":"शह से बचने का सबसे अच्छा तरीका ढूँढें।","ls.b_escape.hint":"लाल फ्रेम आपका राजा है, गुलाबी फ्रेम शह देने वाला मोहरा। अगर उसे मार सकें, तो वही सबसे अच्छा है।","ls.b_escape.why":"{m} सबसे अच्छी चाल है: राजा बचता है और कोई मोहरा नहीं गँवाना पड़ता।","ls.b_mate.title":"शह-मात","ls.b_mate.sub":"इसी से खेल जीतते हैं!","ls.b_mate.intro":"<p>जब शह में पड़ा राजा <b>न हट सके, न बीच में मोहरा रखकर बचाया जा सके, और न शह देने वाले मोहरे को मारा जा सके</b>, तो यह <b>शह-मात</b> है — और मात देने वाला <b>जीत जाता है</b>।</p><p>चित्र में \"बैक-रैंक मात\" है: राजा के अपने ही प्यादे उसका रास्ता रोक रहे हैं।</p>","ls.b_mate.goal":"एक चाल में शह-मात दें।","ls.b_mate.hint":"लाल फ्रेम काला राजा है। ऐसी शह ढूँढिए जिसके बाद उसके पास भागने का कोई खाना न बचे।","ls.b_mate.why":"शह-मात! {m} के बाद काले राजा के पास जाने को कोई जगह नहीं।","ls.b_mate.ng":"यह शह-मात नहीं है। उत्तर: {m}","ls.b_special.title":"विशेष नियम","ls.b_special.sub":"कैसलिंग, आँ पासाँ, प्रमोशन","ls.b_special.intro":"<p><b>कैसलिंग</b>: अगर राजा और एक हाथी अब तक नहीं चले हैं और उनके बीच कोई मोहरा नहीं है, तो <b>राजा को बगल में दो खाने</b> चलाइए; हाथी कूदकर राजा की दूसरी ओर आ जाता है — एक ही चाल में दो मोहरे। शह में होने पर या हमले वाले खाने से गुज़रते हुए यह नहीं कर सकते। इससे आपका राजा सुरक्षित हो जाता है।</p><p><b>आँ पासाँ</b>: विरोधी का प्यादा दो खाने चलकर ठीक आपके प्यादे के <b>बगल में</b> आए, तो ठीक उसी समय आप उसे <b>तिरछा</b> ऐसे मार सकते हैं मानो वह एक ही खाना चला हो।</p><p><b>प्रमोशन</b>: आखिरी पंक्ति पर पहुँचा प्यादा वज़ीर (या कोई और मोहरा) बन जाता है।</p><p class=\"note\">कैसलिंग के लिए राजा को बगल में दो खाने चलाइए।</p>","ls.b_special.goal":"कोई विशेष नियम इस्तेमाल करें (कैसलिंग, आँ पासाँ, प्रमोशन)।","ls.b_special.hint":"सुनहरे फ्रेम वाला मोहरा चलाइए।","ls.b_special.why":"सही! {m}।","ls.b_special.ng":"उत्तर था {m}। कैसलिंग में राजा बगल में दो खाने चलता है; आँ पासाँ में तिरछा मारते हैं; प्रमोशन में वज़ीर चुनिए।","ls.b_draw.title":"बराबरी","ls.b_draw.sub":"स्टेलमेट से सावधान","ls.b_draw.intro":"<p>अगर चलने वाले पक्ष पर <b>शह नहीं है, पर कोई वैध चाल भी नहीं है</b>, तो यह <b>स्टेलमेट</b> है — यानी <b>बराबरी</b>। चित्र में काले राजा पर शह नहीं है, फिर भी जिन खानों पर वह जा सकता है, उन सब पर हमला है।</p><p>जीतती हुई स्थिति में विरोधी को स्टेलमेट कर देना एक आम गलती है: राजा के लिए एक खाना खाली छोड़िए, या शह-मात दीजिए।</p><p class=\"note\">एक ही स्थिति तीन बार आने पर, 50 चालों तक न कुछ मारा जाए न प्यादा चले, या किसी के पास मात देने लायक मोहरे न हों, तब भी खेल बराबरी पर खत्म होता है।</p>","ls.b_draw.goal":"जीत की ओर ले जाने वाली चाल चलें — स्टेलमेट किए बिना।","ls.b_draw.hint":"लाल फ्रेम काला राजा है। आपकी चाल के बाद क्या काले के पास कोई चाल बचती है (या यह मात है)?","ls.b_draw.why":"{m} सबसे अच्छी चाल है: स्टेलमेट नहीं होता और आप जीत के करीब पहुँचते हैं।"},
"ar":{"ls.desc":"لا داعي لمعرفة القواعد. في «الشطرنج من الصفر» تتعلم كل شيء، من حركة القطع حتى لعب مباراة كاملة، بتحريك القطع على الرقعة. بعدها تعلّم أنماط الفوز في «التكتيكات» (20 نقطة لكل مسألة، والنجاح بـ 75).","course.basics":"الشطرنج من الصفر","course.basics.sub":"للمبتدئين تمامًا. حركة القطع ← الأسر ← الكش ← الكش مات ← القواعد الخاصة ← التعادل، تتعلمها بتحريك القطع على الرقعة.","course.tactics":"التكتيكات","course.tactics.sub":"بعد أن تعرف القواعد: كسب المادة، والشوكات، وأنماط الكش مات، وطرق أخرى للفوز.","course.graduate":"🎉 أنهيت «الشطرنج من الصفر» — أصبحت تعرف كل قواعد الشطرنج! جرّب مباراة حقيقية ضد أسهل ذكاء اصطناعي (المستوى 1). أثناء المباراة، المس أي قطعة لترى المربعات التي يمكنها الانتقال إليها.","course.play":"العب ضد الذكاء الاصطناعي (المستوى 1)","dr.start":"المس القطعة (أو اسحبها) لتحريكها واجمع كل ★. الهدف: {p} نقلة.","dr.par":"(الهدف: {p} نقلة)","dr.reset":"إعادة البدء","dr.progress":"النقلة {n}. بقي {left} ★.","dr.clear":"أحسنت!","dr.used":"استخدمت {n} نقلة (الهدف {p}).","dr.tryPar":"اضغط «إعادة البدء» لتحاول بلوغ الهدف.","dr.danger":"هذا المربع مهدَّد — ستُؤسر قطعتك. لا يمكنك التوقف على المربعات المخططة بالأحمر.","dr.more":"ثلاث نجوم تعني أنك أنهيت المرحلة بعدد النقلات المستهدف.","ill.self":"لا يمكنك لعب هذه النقلة: ستترك ملكك عرضة للأسر.","ill.inCheck":"ملكك في حالة كش. يجب أن تحميه أولًا.","ls.b_rook.title":"الرخ","ls.b_rook.sub":"أي مسافة في خط مستقيم: للأمام أو للخلف أو للجانب","ls.b_rook.intro":"<p>يُلعب الشطرنج على <b>رقعة من 8×8 مربعات</b>. يتناوب الأبيض والأسود على تحريك قطعة واحدة في كل دور، ويبدأ الأبيض. <b>تفوز عندما تحاصر ملك خصمك</b> (كش مات). لنتعلم أولًا كيف تتحرك كل قطعة.</p><p><b>الرخ</b> (القطعة التي تشبه القلعة) يتحرك <b>في خط مستقيم أفقيًا أو عموديًا</b>، أي عدد من المربعات. ولا يمكنه القفز فوق القطع الأخرى.</p><p class=\"note\">حرّك الرخ لتجمع كل ★ على الرقعة. النقاط تبيّن المربعات التي يمكنه الوصول إليها.</p>","ls.b_rook.goal":"اجمع كل ★ بالرخ.","ls.b_bishop.title":"الفيل","ls.b_bishop.sub":"أي مسافة قطريًا","ls.b_bishop.intro":"<p><b>الفيل</b> (القطعة ذات القبعة المدببة) يتحرك <b>قطريًا</b>، أي عدد من المربعات.</p><p>ولأنه لا يتحرك إلا قطريًا، <b>يبقى الفيل دائمًا على مربعات من اللون نفسه</b>. لكل طرف فيل للمربعات الفاتحة وفيل للمربعات الداكنة.</p>","ls.b_bishop.goal":"اجمع كل ★ بالفيل.","ls.b_queen.title":"الوزير","ls.b_queen.sub":"أقوى قطعة","ls.b_queen.intro":"<p><b>الوزير</b> (القطعة ذات التاج) يجمع حركة الرخ والفيل: يتحرك <b>في خط مستقيم أو قطريًا</b>، أي عدد من المربعات.</p><p>إنه أقوى قطعة، فاحرص على ألّا تخسره.</p>","ls.b_queen.goal":"اجمع كل ★ بالوزير.","ls.b_king.title":"الملك","ls.b_king.sub":"أهم قطعة","ls.b_king.intro":"<p><b>الملك</b> (القطعة ذات الصليب) يتحرك <b>مربعًا واحدًا في أي اتجاه</b>.</p><p>لا يجوز أن يُؤسر الملك أبدًا. إذا لم يستطع ملكك الإفلات، تخسر.</p>","ls.b_king.goal":"اجمع كل ★ بالملك.","ls.b_knight.title":"الحصان","ls.b_knight.sub":"يقفز على شكل L","ls.b_knight.intro":"<p><b>الحصان</b> يتحرك على <b>شكل L: مربعان في اتجاه ثم مربع واحد إلى الجانب</b>.</p><p>إنه القطعة الوحيدة التي يمكنها <b>القفز فوق</b> القطع الأخرى. ومع كل قفزة يتغير أيضًا لون المربع الذي يقف عليه.</p>","ls.b_knight.goal":"اجمع كل ★ بالحصان.","ls.b_pawn.title":"البيدق","ls.b_pawn.sub":"يتقدم للأمام ويأسر قطريًا","ls.b_pawn.intro":"<p><b>البيدق</b> يتحرك <b>مربعًا واحدًا إلى الأمام</b> ولا يتراجع أبدًا — لكن <b>في أول نقلة له يمكنه التقدم مربعين</b>.</p><p>وهو <b>يأسر مربعًا واحدًا قطريًا إلى الأمام</b>. إذا كانت أمامه مباشرة قطعة، لا يستطيع البيدق التحرك.</p><p>عندما يصل البيدق إلى <b>الطرف الآخر</b> من الرقعة <b>يُرقّى</b> إلى وزير أو رخ أو فيل أو حصان — وغالبًا ما يُختار الوزير.</p>","ls.b_pawn.goal":"اجمع كل ★ بالبيدق.","ls.b_capture.title":"الأسر","ls.b_capture.sub":"انتقل إلى مربع قطعة للخصم","ls.b_capture.intro":"<p>إذا كانت قطعة للخصم على مربع تستطيع قطعتك الوصول إليه، يمكنك الانتقال إليه و<b>أسرها</b>. القطع المأسورة تخرج من الرقعة.</p><p>للقطع قيم تقريبية: <b>البيدق 1، الحصان 3، الفيل 3، الرخ 5، الوزير 9</b>. الاحتفاظ بالقطع الأعلى قيمة يمنحك الأفضلية.</p><p class=\"note\">خذ كل القطع السوداء التي تقف على ★ (القطع السوداء لا تتحرك).</p>","ls.b_capture.goal":"خذ كل القطع السوداء الموجودة على ★.","ls.b_safety.title":"المربعات الآمنة","ls.b_safety.sub":"انتبه لما يهاجمه الخصم","ls.b_safety.intro":"<p>إذا وضعت قطعة في مربع يمكن لقطعة الخصم الوصول إليه، فسيتم <b>أسرها</b> في النقلة التالية.</p><p>في هذا التمرين تظهر المربعات التي تهاجمها القطع السوداء <b>بخطوط حمراء</b>. لا يمكنك التوقف عليها، فابحث عن طريق آخر لتجمع ★.</p><p class=\"note\">في المباريات الحقيقية، اعتد أن تسأل قبل كل نقلة: «هل هذا المربع مهدَّد؟»</p>","ls.b_safety.goal":"اجمع ★ عبر المربعات الآمنة فقط.","ls.b_check.title":"الكش","ls.b_check.sub":"هاجم الملك","ls.b_check.intro":"<p>النقلة التي <b>تهاجم ملك الخصم</b> تُسمّى <b>كش</b>.</p><p>على الطرف الواقع في الكش أن يحمي ملكه في النقلة التالية مباشرة. من هنا تُطبَّق القواعد كاملة: اختر نقلة واحدة للأبيض.</p>","ls.b_check.goal":"هاجم الملك الأسود بكش.","ls.b_check.hint":"الإطار الأحمر هو الملك الأسود. ابحث عن خط أو قفزة تصل إليه.","ls.b_check.why":"صحيح! {m} كش.","ls.b_check.ng":"هذه النقلة ليست كشًّا. إحدى الإجابات: {m}","ls.b_escape.title":"الخروج من الكش","ls.b_escape.sub":"ثلاث طرق للدفاع","ls.b_escape.intro":"<p>عندما تكون في حالة كش، عليك أن تفعل واحدًا من ثلاثة:</p><p>① <b>تحريك الملك</b> إلى مربع آمن<br>② <b>الحجز</b> بوضع قطعة في الوسط (لا يصلح ضد الحصان)<br>③ <b>أسر</b> القطعة التي تعطي الكش</p><p>النقلات التي تتجاهل الكش غير مسموحة. فكّر في أفضل دفاع.</p>","ls.b_escape.goal":"جد أفضل طريقة للخروج من الكش.","ls.b_escape.hint":"الإطار الأحمر هو ملكك، والإطار الوردي هو القطعة التي تعطي الكش. إن استطعت أسرها فهذا الأفضل.","ls.b_escape.why":"{m} هي الأفضل: تنقذ الملك دون خسارة مادة.","ls.b_mate.title":"الكش مات","ls.b_mate.sub":"بهذا تفوز بالمباراة!","ls.b_mate.intro":"<p>عندما يكون الملك في كش و<b>لا يستطيع الهروب، ولا يمكن الحجز بقطعة، ولا يمكن أسر القطعة التي تعطي الكش</b>، فهذا <b>كش مات</b> — ومن فعله <b>يفوز</b>.</p><p>يُظهر الشكل «مات الصف الخلفي»: بيادق الملك نفسه تسدّ عليه طريق الهروب.</p>","ls.b_mate.goal":"اكش مات في نقلة واحدة.","ls.b_mate.hint":"الإطار الأحمر هو الملك الأسود. جد كشًّا لا يترك له أي مربع هروب.","ls.b_mate.why":"كش مات! بعد {m} لا يجد الملك الأسود مكانًا يذهب إليه.","ls.b_mate.ng":"هذا ليس كش مات. الإجابة: {m}","ls.b_special.title":"قواعد خاصة","ls.b_special.sub":"التبييت، الأخذ في الممر، الترقية","ls.b_special.intro":"<p><b>التبييت</b>: إذا لم يتحرك الملك ولا الرخ من قبل ولم تكن بينهما قطع، حرّك <b>الملك مربعين إلى الجانب</b>، فيقفز الرخ إلى الجهة الأخرى من الملك — قطعتان في نقلة واحدة. لا يجوز ذلك أثناء الكش ولا بالمرور عبر مربع مهدَّد. إنه يضع ملكك في مكان آمن.</p><p><b>الأخذ في الممر</b>: مباشرة بعد أن يتقدم بيدق الخصم مربعين ويقف <b>بجوار</b> بيدقك، يمكنك أسره <b>قطريًا</b> كأنه تقدم مربعًا واحدًا.</p><p><b>الترقية</b>: البيدق الذي يصل إلى الصف الأخير يصبح وزيرًا (أو قطعة أخرى).</p><p class=\"note\">للتبييت، حرّك الملك مربعين إلى الجانب.</p>","ls.b_special.goal":"استخدم قاعدة خاصة (التبييت، الأخذ في الممر، الترقية).","ls.b_special.hint":"حرّك القطعة ذات الإطار الذهبي.","ls.b_special.why":"صحيح! {m}.","ls.b_special.ng":"الإجابة كانت {m}. للتبييت حرّك الملك مربعين إلى الجانب؛ الأخذ في الممر يكون قطريًا؛ وفي الترقية اختر الوزير.","ls.b_draw.title":"التعادل","ls.b_draw.sub":"احذر الجمود","ls.b_draw.intro":"<p>إذا كان الطرف الذي عليه الدور <b>ليس في كش لكنه لا يملك أي نقلة قانونية</b>، فهذا <b>جمود</b> — أي <b>تعادل</b>. في الشكل، الملك الأسود ليس في كش، لكن كل مربع يمكن أن ينتقل إليه مهدَّد.</p><p>إيقاع الخصم في الجمود وأنت متقدم خطأ شائع: اترك للملك مربعًا، أو اكش مات.</p><p class=\"note\">تنتهي المباراة بالتعادل أيضًا عند تكرار الوضع نفسه ثلاث مرات، أو بعد 50 نقلة بلا أسر ولا تحريك بيدق، أو حين لا يملك أي طرف ما يكفي للكش مات.</p>","ls.b_draw.goal":"العب نقلة رابحة — دون جمود.","ls.b_draw.hint":"الإطار الأحمر هو الملك الأسود. بعد نقلتك، هل يبقى للأسود نقلة (أم أنه كش مات)؟","ls.b_draw.why":"{m} هي الأفضل: لا جمود، وتقرّبك من الفوز."}};
const I = window.I18N;
for (const l in B) if (I[l]) Object.assign(I[l], B[l]);
})();
